-- The paragon board (mod-stat-growth ParagonSystem.cpp).
--
-- Talking to the keeper in Stormwind opens this. The board itself comes from ParagonBoard.lua, shipped in the
-- same patch and generated by the same script as the server's copy; the server only ever sends this frame the
-- character's own state, because an addon whisper caps at 255 bytes and 241 nodes would be a hundred of them.
--
-- The server decides what may be allocated. Everything here is presentation: a node the frame thinks is legal
-- is still checked before anything is spent.

local PREFIX = "Paragon"
local rescaleLabels

local WINDOW_WIDTH, WINDOW_HEIGHT = 940, 640
-- The board fills the window: the same rectangle as the panel ground, so it runs under the border art on
-- every side rather than stopping short of it. Everything else - the points orb, its text, the reset button -
-- floats on top of the board instead of sitting in a margin beside it.
local CANVAS_LEFT, CANVAS_TOP = 2, 21
local CANVAS_RIGHT, CANVAS_BOTTOM = 2, 2
-- The board's size comes with the board (ParagonBoard.lua): its outermost node plus a margin, so there is no
-- empty ground to pan into, which is what let the board shrink away from the viewport.
local BOARD_EXTENT = ParagonBoard.extent or 1700
-- Twice as wide as tall: zoomed right out, the whole sky fits the window's height with stars either side of it, and a
-- scroll frame cannot scroll past its child's edge, so the child has to be at least the window's shape
local BOARD_WIDTH, BOARD_HEIGHT = BOARD_EXTENT * 2, BOARD_EXTENT
local NODE_SIZE = { [0] = 44, [1] = 60, [2] = 80 }
-- Fraction of the node the icon is drawn at, per socket. Each is wider than that socket's hole, so the ring
-- drawing over it crops the square icon into the circle of the hole; an icon smaller than the hole just
-- shows its own square edge. The margin at both ends has to be real: the keystone once cleared its metal by
-- one part in two hundred, which satisfied the geometry and was still plainly a square at eighty pixels.
-- buildParagonArt.py narrows every socket's hole until these sizes have room, so the two move together.
local ICON_SCALE = { [0] = 0.57, [1] = 0.57, [2] = 0.47 }
-- How wide the spark that runs along a link is drawn. The links themselves carry no width here any more:
-- each one is a texture with the bar already drawn into it at LINK_THICKNESS board units (buildParagonArt.py).
local SPARK_SIZE = 28

-- Zoomed right out, the whole sky fits the window: the three inner zones are a coin at its centre and every node is a
-- star. Each wheel step zooms by the same factor, so the far end is as quick to reach as the near one.
local MIN_ZOOM, MAX_ZOOM, ZOOM_FACTOR = 0.04, 1.8, 1.15
-- Opens showing the hub and the first few rings rather than the whole board. Fitting all 217 nodes in the
-- window puts them at 17 pixels, which is unreadable; the far half of the tree is meant to be panned to.
local DEFAULT_ZOOM = 0.85

-- Locked branches stay visible but clearly out of reach: seeing what you are not going to get is most of what
-- a board this size is for. Not so faint they turn into texture, though - that was the first attempt.
local ALPHA_LOCKED, ALPHA_REACHABLE, ALPHA_TAKEN = 0.55, 0.85, 1.0

-- A node behind a shut tier gate (its branch's previous zone not yet complete) sits darker still, under a lock
local ALPHA_SEALED = 0.4

local TINT_LOCKED    = { 0.32, 0.32, 0.30 }
local TINT_REACHABLE = { 0.72, 0.62, 0.42 }
local TINT_TAKEN     = { 1.0, 0.78, 0.32 }

local SOUND_OPEN      = "AchievementMenuOpen"
local SOUND_CLOSE     = "AchievementMenuClose"
local SOUND_HOVER     = "GAMESCREENSMALLBUTTONMOUSEOVER"
local SOUND_MINOR     = "Glyph_MinorCreate"      -- inscribing minor power; the small click
local SOUND_NOTABLE   = "Glyph_MajorCreate"      -- the same sound with weight behind it
local SOUND_KEYSTONE  = "LEVELUPSOUND"           -- layered over the glyph, never instead of it
local SOUND_RESET     = "Glyph_MajorDestroy"     -- audibly the reverse of MajorCreate
local SOUND_DENIED    = "igQuestFailed"

local ART = "Interface\\Paragon\\"

-- The Panthéon and the glyphs (ParagonBoard.lua carries their data)
local SOCKET_EFFECT = ParagonBoard.socketEffect or 26
local GLYPH_RADIUS = ParagonBoard.glyphRadius or 3
local GLYPH_MAX_LEVEL = ParagonBoard.glyphMaxLevel or 25
local PANTHEON_TIER = 3
-- Legendary orange, for the glyphs and their sockets, as the game draws a legendary item
local LEGENDARY = { 1, 0.5, 0 }
-- A sigil's lines: faint until it is complete, then the board's gold
local SIGIL_FAINT = { 0.55, 0.52, 0.85 }
local MORPHEUS = "Fonts\\MORPHEUS.ttf"   -- headings only (the title, zone names, the big point count)
local FRIZ = "Fonts\\FRIZQT__.TTF"        -- the numbers on the nodes
local POINT_FONT_SIZE = 26

-- The three kinds of node, as the tooltip and the legend name them
local NODE_KINDS = {
    [0] = { label = "Mineur", color = { 0.75, 0.75, 0.75 }, ring = "Paragon-Node-Minor" },
    [1] = { label = "Notable", color = { 0.35, 0.65, 1 }, ring = "Paragon-Node-Notable" },
    [2] = { label = "Clé de voûte", color = { 1, 0.5, 0 }, ring = "Paragon-Node-Keystone" },
}

local state = {
    open = false,
    cap = 100,
    level = 0,                              -- paragon level: experience at the level cap
    experience = 0,
    needed = 1,
    available = 0,
    earned = 0,
    spent = 0,
    allocated = {},
    pending = nil,                          -- node waiting on the server's answer
    receiving = false,
    loadouts = {},                          -- the saved configurations: { slot, points, name }
    activeLoadout = nil,                    -- the slot the board was last taken from or saved to
    activePreset = nil,                     -- the recommended board last applied (1 raid, 2 Mythique+)
}

local frame, canvas, board, hud, pointText, spentText, statusText
local refreshLoadouts                       -- the configuration picker's text, once the window exists
local pointGlow, spentFill, bonusPanel, bonusText
local levelText, levelFill, levelBarText
local nodeButtons, linkTextures = {}, {}
-- The glyphs this character knows: [id] = { level, experience, needed, socket }, and which glyph sits in each socket
local glyphState, socketGlyph = {}, {}
local glyphByItem = {}
for id, glyph in pairs(ParagonBoard.glyphs or {}) do
    glyphByItem[glyph.item] = id
end
-- Which sigil each node belongs to is on the node; which sigils are complete is counted with the tiers
local sigilComplete = {}
local glyphPanel, glyphButtons, scaledLabels = nil, {}, {}
-- The nodes one click away, kept by refreshAll: they breathe while there are points to spend
local reachableButtons = {}
local shownAvailable
local adjacency = {}
local animations = {}

--------------------------------------------------------------------------------
-- Board helpers
--------------------------------------------------------------------------------

local function buildAdjacency()
    if next(adjacency) then return end
    for _, link in ipairs(ParagonBoard.links) do
        local a, b = link[1], link[2]
        adjacency[a] = adjacency[a] or {}
        adjacency[b] = adjacency[b] or {}
        table.insert(adjacency[a], b)
        table.insert(adjacency[b], a)
    end
end

local function isAllocated(id)
    local node = ParagonBoard.nodes[id]
    if not node then return false end
    if node.free then return true end
    return state.allocated[id] == true
end

-- What a node costs: 1 for a small one, up to 5 for an Apotheosis (the same numbers the server charges)
local function nodeCost(node)
    if not node or node.free then return 0 end
    return math.max(1, node.cost or 1)
end

-- Every paid node of a side's tier, by side then tier: a side's next tier opens once all of these are held
local NO_SIDE = 255
local tierNodes
local tierMissing = {}

local function buildTiers()
    if tierNodes then return end
    tierNodes = {}
    for id, node in pairs(ParagonBoard.nodes) do
        local side = node.side or NO_SIDE
        if not node.free and side ~= NO_SIDE then
            tierNodes[side] = tierNodes[side] or {}
            local tier = node.tier or 0
            tierNodes[side][tier] = tierNodes[side][tier] or {}
            table.insert(tierNodes[side][tier], id)
        end
    end
end

-- How many nodes of each side's tier are still missing, recounted whenever the allocation changes; and which of the
-- Panthéon's sigils are wholly taken, which lights their lines
local function countTiers()
    buildTiers()
    tierMissing = {}
    for side, tiers in pairs(tierNodes) do
        tierMissing[side] = {}
        for tier, ids in pairs(tiers) do
            local missing = 0
            for _, id in ipairs(ids) do
                if not state.allocated[id] then missing = missing + 1 end
            end
            tierMissing[side][tier] = missing
        end
    end
    sigilComplete = {}
    for index, sigil in pairs(ParagonBoard.sigils or {}) do
        local complete = true
        for _, id in ipairs(sigil.nodes) do
            if not state.allocated[id] then
                complete = false
                break
            end
        end
        sigilComplete[index] = complete
    end
end

--------------------------------------------------------------------------------
-- Glyph helpers
--------------------------------------------------------------------------------

-- The nodes within GLYPH_RADIUS links of a socket, found once
local socketReach = {}
local function reachOf(socket)
    if socketReach[socket] then return socketReach[socket] end
    local seen, frontier, reach = { [socket] = true }, { socket }, {}
    for _ = 1, GLYPH_RADIUS do
        local nextFrontier = {}
        for _, at in ipairs(frontier) do
            for _, neighbour in ipairs(adjacency[at] or {}) do
                if not seen[neighbour] then
                    seen[neighbour] = true
                    table.insert(nextFrontier, neighbour)
                    table.insert(reach, neighbour)
                end
            end
        end
        frontier = nextFrontier
    end
    socketReach[socket] = reach
    return reach
end

-- A glyph's share of the nodes it reaches, in percent (the server's GlyphShare)
local function glyphShare(level)
    return 10 + 2 * math.min(level or 1, GLYPH_MAX_LEVEL)
end

-- How many allocated nodes of a glyph's branch its socket reaches, against what its bonus needs
local function glyphCondition(glyphId, socket)
    local glyph = ParagonBoard.glyphs[glyphId]
    if not glyph or not socket or socket == 0 then return 0, glyph and glyph.need or 0 end
    local own = 0
    for _, id in ipairs(reachOf(socket)) do
        local node = ParagonBoard.nodes[id]
        if node and node.side == glyph.side and isAllocated(id) then own = own + 1 end
    end
    return own, glyph.need
end

local function sideName(side)
    return ParagonBoard.sides and ParagonBoard.sides[side] or ""
end

local function isSocket(id)
    local node = ParagonBoard.nodes[id]
    return node and node.effect == SOCKET_EFFECT
end

-- The nodes still missing before this node's tier opens on its side (0: open). The hub, the bridges and the first
-- tier are never gated.
local function tierGate(id)
    local node = ParagonBoard.nodes[id]
    local side, tier = node and node.side or NO_SIDE, node and node.tier or 0
    if side == NO_SIDE or tier == 0 then return 0 end
    return (tierMissing[side] and tierMissing[side][tier - 1]) or 0
end

local function tierName(tier)
    local zone = ParagonBoard.zones and ParagonBoard.zones[tier + 1]
    return zone and zone.name or tostring(tier)
end

-- Points a node needs spent on the board before it can be taken (the first zone's keystones), or its tier still shut
local function isGated(id)
    local node = ParagonBoard.nodes[id]
    return node and ((node.required or 0) > state.spent or tierGate(id) > 0)
end

-- Reachable means "next to something already held" and past its gate, the same rules the server enforces.
local function isReachable(id)
    if isAllocated(id) or isGated(id) then return false end
    for _, neighbour in ipairs(adjacency[id] or {}) do
        if isAllocated(neighbour) then return true end
    end
    return false
end

--------------------------------------------------------------------------------
-- Line drawing
--------------------------------------------------------------------------------

-- Placing a link between two nodes.
--
-- The usual way to draw a line in 3.3.5 is to rotate one bar texture with the eight-argument SetTexCoord.
-- That does not survive here. The coordinates that trick needs for a long thin bar run far outside [0,1] -
-- up to 3.3 and -2.3 on this board - and the client does not draw them: the only links that came out right
-- were the horizontals, whose coordinates are exactly 0 and 1. Every rotated one rendered as a sliver or an
-- elbow.
--
-- So the rotation is baked into the art. localTools/interface/buildParagonArt.py emits one texture per
-- distinct link shape on the board, with the bar already drawn corner to corner, and this only has to place
-- it square. One texel is one board unit, and the board carries the zoom on its own scale, so the size is
-- fixed once and never recomputed.
local LINK_PAD = 12        -- must match LINK_PAD in buildParagonArt.py

local function potAtLeast(value)
    local size = 16
    while size < value do
        size = size * 2
    end
    return size
end

local function placeLink(texture, parent, sx, sy, ex, ey)
    local dx, dy = ex - sx, ey - sy
    local spanX, spanY = math.abs(dx), math.abs(dy)
    if spanX + spanY < 1 then
        texture:Hide()
        return
    end

    texture:SetTexture(ART .. string.format("Paragon-Link-%dx%d", spanX, spanY))
    -- The art is drawn in the "/" sense; the other diagonal is the same picture mirrored.
    if (dx < 0) ~= (dy < 0) then
        texture:SetTexCoord(1, 0, 0, 1)
    else
        texture:SetTexCoord(0, 1, 0, 1)
    end

    texture:ClearAllPoints()
    texture:SetSize(potAtLeast(spanX + LINK_PAD), potAtLeast(spanY + LINK_PAD))
    texture:SetPoint("CENTER", parent, "BOTTOMLEFT", (sx + ex) / 2, (sy + ey) / 2)
    texture:Show()
end

-- The Panthéon's links are too many and too varied to have a texture each. They share a set drawn by angle (every
-- SKY_ANGLE_STEP degrees) and length (SKY_LENGTHS), at SKY_TEXEL board units a texel (buildParagonArt.py's
-- buildSkyLinkTextures, which must agree), and each is stretched to its exact span: the ends land where they belong,
-- and the bar's width moves by a few percent at most. Near the axes the bar is kept at its width instead.
local SKY_ANGLE_STEP = 3
local SKY_LENGTHS = { 112, 176, 272, 432 }
local SKY_TEXEL, SKY_PAD = 2, 6
local SKY_KEEP_WIDTH = 20

local function skyLinkShape(dx, dy)
    local spanX, spanY = math.abs(dx), math.abs(dy)
    local length = math.sqrt(spanX * spanX + spanY * spanY)
    local angle = math.floor(math.deg(math.atan2(spanY, spanX)) / SKY_ANGLE_STEP + 0.5) * SKY_ANGLE_STEP
    local nominal = SKY_LENGTHS[1]
    for _, candidate in ipairs(SKY_LENGTHS) do
        if math.abs(math.log(candidate / length)) < math.abs(math.log(nominal / length)) then nominal = candidate end
    end
    local boxX = math.floor(nominal * math.cos(math.rad(angle)) + 0.5)
    local boxY = math.floor(nominal * math.sin(math.rad(angle)) + 0.5)
    return angle, nominal, boxX, boxY, spanX, spanY
end

local function placeSkyLink(texture, parent, sx, sy, ex, ey)
    local dx, dy = ex - sx, ey - sy
    if math.abs(dx) + math.abs(dy) < 1 then
        texture:Hide()
        return
    end
    local angle, nominal, boxX, boxY, spanX, spanY = skyLinkShape(dx, dy)
    texture:SetTexture(ART .. string.format("Paragon-SkyLink-%d-%d", angle, nominal))
    if (dx < 0) ~= (dy < 0) then
        texture:SetTexCoord(1, 0, 0, 1)
    else
        texture:SetTexCoord(0, 1, 0, 1)
    end
    local width = potAtLeast(boxX / SKY_TEXEL + SKY_PAD) * SKY_TEXEL
    local height = potAtLeast(boxY / SKY_TEXEL + SKY_PAD) * SKY_TEXEL
    local scaleX = boxX >= SKY_KEEP_WIDTH and spanX / boxX or 1
    local scaleY = boxY >= SKY_KEEP_WIDTH and spanY / boxY or 1
    texture:ClearAllPoints()
    texture:SetSize(width * scaleX, height * scaleY)
    texture:SetPoint("CENTER", parent, "BOTTOMLEFT", (sx + ex) / 2, (sy + ey) / 2)
    texture:Show()
end

-- Labels that keep a readable size however far the board is zoomed out: the Panthéon's name and its Titans'. Each
-- lives in a frame of its own whose scale undoes the board's, within bounds.
local function placeScaledLabel(entry, scale)
    entry.holder:SetScale(scale)
    entry.holder:ClearAllPoints()
    entry.holder:SetPoint("CENTER", board, "BOTTOMLEFT", entry.x / scale, entry.y / scale)
end

rescaleLabels = function()
    if not board then return end
    local zoom = board:GetScale()
    for _, entry in ipairs(scaledLabels) do
        local scale = math.max(1, math.min(entry.maxScale, entry.screen / zoom))
        if math.abs(scale - (entry.scale or 0)) > 0.01 then
            entry.scale = scale
            placeScaledLabel(entry, scale)
        end
    end
end

--------------------------------------------------------------------------------
-- Animation: the cascade when a node is taken
--------------------------------------------------------------------------------

local function addAnimation(entry)
    entry.elapsed = 0
    table.insert(animations, entry)
end

local function updateAnimations(elapsed)
    for index = #animations, 1, -1 do
        local animation = animations[index]
        animation.elapsed = animation.elapsed + elapsed
        local progress = animation.elapsed / animation.duration
        if progress >= 1 then
            animation.finish(animation)
            table.remove(animations, index)
        else
            animation.step(animation, progress)
        end
    end
end

-- The node swells and settles. Small, but it is what makes a click feel like it landed.
local function animateNode(button)
    local base = button.baseSize
    addAnimation({
        duration = 0.35,
        step = function(_, progress)
            local scale = progress < 0.4 and (1 + 0.3 * (progress / 0.4))
                or (1.3 - 0.3 * ((progress - 0.4) / 0.6))
            button:SetSize(base * scale, base * scale)
        end,
        finish = function() button:SetSize(base, base) end,
    })
end

-- The link behind it lights up as a spark runs along it. This is the part people remember, so it is the part
-- worth the frames.
local function animateLink(texture, sx, sy, ex, ey)
    local spark = board.sparkPool[#board.sparkPool]
    if not spark then return end
    table.remove(board.sparkPool)

    -- The comet has a nose and a tail, so it has to point the way it is travelling. Its art is generated
    -- already turned along the link, pointing up and to the right; the other three directions are the same
    -- picture flipped on one or both axes, which are ordinary in-range texture coordinates.
    local dx, dy = ex - sx, ey - sy
    if texture.sky then
        spark:SetTexture(ART .. string.format("Paragon-SkyLink-Spark-%d", (skyLinkShape(dx, dy))))
    else
        spark:SetTexture(ART .. string.format("Paragon-Link-Spark-%dx%d", math.abs(dx), math.abs(dy)))
    end
    local left, right = 0, 1
    local top, bottom = 0, 1
    if dx < 0 then left, right = 1, 0 end
    if dy < 0 then top, bottom = 1, 0 end
    spark:SetTexCoord(left, right, top, bottom)

    spark:SetAlpha(1)
    spark:Show()
    addAnimation({
        duration = 0.25,
        step = function(_, progress)
            spark:ClearAllPoints()
            spark:SetPoint("CENTER", board, "BOTTOMLEFT",
                sx + (ex - sx) * progress, sy + (ey - sy) * progress)
            texture:SetVertexColor(1, 0.85 + 0.15 * progress, 0.4 + 0.5 * progress)
        end,
        finish = function()
            spark:Hide()
            table.insert(board.sparkPool, spark)
        end,
    })
end

-- Newly reachable neighbours fade in a few frames apart, so the change ripples outward instead of popping.
local function animateRipple(button, delay)
    addAnimation({
        duration = delay + 0.25,
        step = function(_, progress)
            local total = delay + 0.25
            local started = (progress * total) - delay
            if started > 0 then
                button:SetAlpha(ALPHA_LOCKED + (ALPHA_REACHABLE - ALPHA_LOCKED) * (started / 0.25))
            end
        end,
        finish = function() button:SetAlpha(ALPHA_REACHABLE) end,
    })
end

local function flashCanvas()
    local flash = board.flash
    flash:SetAlpha(0.16)
    flash:Show()
    addAnimation({
        duration = 0.5,
        step = function(_, progress) flash:SetAlpha(0.16 * (1 - progress)) end,
        finish = function() flash:Hide() end,
    })
end

--------------------------------------------------------------------------------
-- Rendering
--------------------------------------------------------------------------------

-- Zoomed right out, a node is a star: its glow alone, larger and brighter, pale where it is not taken. The change is a
-- crossfade over a band of zoom (updateCulling): each node carries how far into it it is, from 0 (the node) to 1 (the
-- star), and its art fades out as its star fades in.
local TINT_STAR = { 0.72, 0.76, 1.0 }
-- The links fade along with the nodes, to this share at the star end; a sigil's own lines stay, they are its figure
local LINK_STAR_FADE = 0.3
local linkFade = 1

local function mix(from, to, t)
    return from + (to - from) * t
end

local function refreshNode(id)
    local button = nodeButtons[id]
    if not button then return end

    local taken, reachable = isAllocated(id), isReachable(id)
    local sealed = not taken and tierGate(id) > 0
    local tint = taken and TINT_TAKEN or (reachable and TINT_REACHABLE or TINT_LOCKED)
    local alpha = sealed and ALPHA_SEALED or ALPHA_LOCKED
    if button.socket then
        -- A socket shows the glyph it holds, in the legendary colour
        local glyph = ParagonBoard.glyphs and ParagonBoard.glyphs[socketGlyph[id] or 0]
        button.icon:SetTexture(glyph and glyph.icon or ParagonBoard.nodes[id].icon)
        if taken then tint = LEGENDARY end
    end
    local t = button.starLevel or 0
    local star = taken and tint or TINT_STAR
    local nodeAlpha = taken and ALPHA_TAKEN or (reachable and ALPHA_REACHABLE or alpha)
    local glowAlpha = taken and 0.5 or (reachable and 0.28 or 0.08)
    local starAlpha = taken and 1 or (reachable and 0.75 or (sealed and 0.3 or 0.45))
    button:SetAlpha(mix(nodeAlpha, 1, t))
    button.glow:SetVertexColor(mix(tint[1], star[1], t), mix(tint[2], star[2], t), mix(tint[3], star[3], t))
    button.glow:SetAlpha(mix(glowAlpha, starAlpha, t))
    button.icon:SetDesaturated(not taken)
    if button.lock then
        if sealed and t < 1 then button.lock:Show() else button.lock:Hide() end
    end
end

local function refreshLinks()
    for _, link in ipairs(linkTextures) do
        local lit = isAllocated(link.a) and isAllocated(link.b)
        if link.sigil and sigilComplete[link.sigil] then
            -- A completed sigil burns: its whole figure at full brightness
            link.texture:SetVertexColor(1, 0.86, 0.5)
            link.texture:SetAlpha(1)
        elseif link.sigil and not lit then
            link.texture:SetVertexColor(SIGIL_FAINT[1], SIGIL_FAINT[2], SIGIL_FAINT[3])
            link.texture:SetAlpha((isAllocated(link.a) or isAllocated(link.b)) and 0.7 or 0.35)
        elseif lit then
            link.texture:SetVertexColor(1, 0.85, 0.45)
            link.texture:SetAlpha(link.sigil and 1 or linkFade)
        else
            local live = isAllocated(link.a) or isAllocated(link.b)
            link.texture:SetVertexColor(0.62, 0.72, 0.95)
            link.texture:SetAlpha((live and 0.8 or 0.42) * linkFade)
        end
    end
end

-- The figure swells and settles when points come in, so a gain is seen even with the eye on the board
local function popPoints()
    addAnimation({
        duration = 0.45,
        step = function(_, progress)
            local swell = progress < 0.3 and (progress / 0.3) or (1 - (progress - 0.3) / 0.7)
            pointText:SetFont(MORPHEUS, POINT_FONT_SIZE + 14 * swell)
        end,
        finish = function() pointText:SetFont(MORPHEUS, POINT_FONT_SIZE) end,
    })
end

local function refreshHeader()
    -- What is left to spend, big; what is already on the board, as a gauge against the cap
    pointText:SetText(state.available)
    pointText:SetTextColor(unpack(state.available > 0 and { 1, 1, 1 } or { 0.6, 0.6, 0.6 }))
    spentText:SetFormattedText("%d / %d |cffaaaaaadépensés|r", state.spent, state.cap)
    local share = state.cap > 0 and math.min(1, state.spent / state.cap) or 0
    spentFill:SetWidth(math.max(1, spentFill.full * share))

    local banked = state.earned - state.cap
    if banked > 0 then
        statusText:SetFormattedText("|cff888888%d en réserve|r", banked)
    else
        statusText:SetText("")
    end

    if levelText then
        levelText:SetFormattedText("Niveau de parangon %d", state.level)
        local share = state.needed > 0 and math.min(1, state.experience / state.needed) or 0
        levelFill:SetWidth(math.max(1, levelFill.full * share))
        levelBarText:SetFormattedText("%d / %d", state.experience, state.needed)
    end

    if shownAvailable and state.available > shownAvailable and frame:IsShown() then
        popPoints()
    end
    shownAvailable = state.available
end

-- Everything the board gives, added up: the flat stats of the minor nodes summed by stat ("+8 Force" five times
-- is "+40 Force"), the notables and keystones by name
-- The summary's room: from under the points block to above the legend line, and its text beside the scroll bar
local BONUS_MAX_HEIGHT = 360
local BONUS_TEXT_WIDTH = 184

local function refreshBonus()
    if not bonusText then return end

    local totals, order, majors = {}, {}, {}
    for id, node in pairs(ParagonBoard.nodes) do
        if isAllocated(id) and not node.free then
            local amount, stat = string.match(node.description or "", "^%+(%d+)%s+(.+)$")
            if node.type == 0 and amount then
                if not totals[stat] then
                    totals[stat] = 0
                    table.insert(order, stat)
                end
                totals[stat] = totals[stat] + tonumber(amount)
            else
                local kind = NODE_KINDS[node.type] or NODE_KINDS[0]
                table.insert(majors, string.format("|cff%02x%02x%02x%s|r", kind.color[1] * 255,
                    kind.color[2] * 255, kind.color[3] * 255, node.name))
            end
        end
    end

    table.sort(order)
    local lines = {}
    for _, stat in ipairs(order) do
        table.insert(lines, string.format("|cffffd98c+%d|r %s", totals[stat], stat))
    end
    -- The Panthéon's Blessings earned, and the glyphs set with whether their bonus holds
    for index, sigil in pairs(ParagonBoard.sigils or {}) do
        if sigilComplete[index] then
            table.insert(majors, string.format("|cffff8000%s|r", sigil.blessing))
        end
    end
    for glyphId, glyph in pairs(glyphState) do
        local data = ParagonBoard.glyphs[glyphId]
        if data and glyph.socket > 0 and isAllocated(glyph.socket) then
            local own, need = glyphCondition(glyphId, glyph.socket)
            table.insert(majors, string.format("|cffff8000%s|r |cffc8b89a(niv. %d%s)|r", data.name, glyph.level,
                own >= need and ", bonus actif" or ""))
        end
    end
    if #majors > 0 then
        table.sort(majors)
        table.insert(lines, " ")
        for _, name in ipairs(majors) do
            table.insert(lines, name)
        end
    end
    bonusText:SetText(#lines > 0 and table.concat(lines, "\n") or "|cff888888Aucun nœud acquis pour l'instant.|r")
    if glyphPanel and glyphPanel:IsShown() then glyphPanel.refresh() end
    local textHeight = bonusText:GetStringHeight()
    bonusPanel:SetHeight(math.min(BONUS_MAX_HEIGHT, textHeight + 48))
    bonusPanel.content:SetHeight(textHeight + 4)
    bonusPanel.scroll:UpdateScrollChildRect()
end

local function refreshAll()
    countTiers()
    reachableButtons = {}
    for id in pairs(ParagonBoard.nodes) do
        refreshNode(id)
        if nodeButtons[id] and isReachable(id) then
            table.insert(reachableButtons, nodeButtons[id])
        end
    end
    refreshLinks()
    refreshHeader()
    refreshBonus()
    if refreshLoadouts then refreshLoadouts() end
end

--------------------------------------------------------------------------------
-- Frame construction
--------------------------------------------------------------------------------

local function nodePosition(node)
    return (BOARD_WIDTH / 2) + node.x, (BOARD_HEIGHT / 2) + node.y
end

local PENDING_TIMEOUT = 3.0

local function allocate(id)
    if state.pending then return end
    if not isReachable(id) then
        PlaySound(SOUND_DENIED)
        local missing = tierGate(id)
        if not isAllocated(id) and missing > 0 then
            local node = ParagonBoard.nodes[id]
            UIErrorsFrame:AddMessage(string.format(
                "Prenez d'abord tous les nœuds de %s de cette branche (%d restants).",
                tierName(node.tier - 1), missing), 1, 0.3, 0.3, 1, 3)
        end
        return
    end
    local cost = nodeCost(ParagonBoard.nodes[id])
    if state.available < cost then
        PlaySound(SOUND_DENIED)
        UIErrorsFrame:AddMessage(state.available <= 0 and "Aucun point de parangon disponible."
            or string.format("Ce nœud coûte %d points (%d disponibles).", cost, state.available), 1, 0.3, 0.3, 1, 3)
        return
    end

    state.pending = id
    state.pendingAt = GetTime()
    SendAddonMessage(PREFIX, "ALLOC\t" .. id, "WHISPER", UnitName("player"))
end

local function onNodeEnter(self)
    local node = ParagonBoard.nodes[self.nodeId]
    PlaySound(SOUND_HOVER)
    -- Anchored right by default, but a node on the right of the screen would push the tooltip off it
    local centre = self:GetLeft()
    local side = (centre and centre > UIParent:GetWidth() * 0.6) and "ANCHOR_LEFT" or "ANCHOR_RIGHT"
    GameTooltip:SetOwner(self, side)
    GameTooltip:AddLine(node.name, 1, 0.82, 0.35)
    local kind = NODE_KINDS[node.type] or NODE_KINDS[0]
    GameTooltip:AddLine(kind.label, kind.color[1], kind.color[2], kind.color[3])
    GameTooltip:AddLine(node.description, 1, 1, 1, true)
    if node.sigil and ParagonBoard.sigils and ParagonBoard.sigils[node.sigil] then
        local sigil = ParagonBoard.sigils[node.sigil]
        local held = 0
        for _, star in ipairs(sigil.nodes) do
            if isAllocated(star) then held = held + 1 end
        end
        GameTooltip:AddLine(string.format("Sigille de %s, %s (%d / %d étoiles)", sigil.titan, sigil.epithet, held,
            #sigil.nodes), 0.78, 0.74, 1)
        local r, g, b = unpack(sigilComplete[node.sigil] and LEGENDARY or { 0.85, 0.8, 0.7 })
        GameTooltip:AddLine(sigil.blessing .. " : " .. sigil.description, r, g, b, true)
    end
    if node.effect == SOCKET_EFFECT then
        local glyphId = socketGlyph[self.nodeId]
        local glyph = glyphId and ParagonBoard.glyphs[glyphId]
        if glyph then
            local known = glyphState[glyphId]
            local own, need = glyphCondition(glyphId, self.nodeId)
            GameTooltip:AddLine(" ")
            GameTooltip:AddLine(string.format("%s (niveau %d)", glyph.name, known.level), LEGENDARY[1], LEGENDARY[2],
                LEGENDARY[3])
            GameTooltip:AddLine(string.format("Les nœuds pris autour de cette châsse sont renforcés de %d%%.",
                glyphShare(known.level)), 1, 0.86, 0.55, true)
            GameTooltip:AddLine("Bonus : " .. glyph.description, own >= need and 1 or 0.62,
                own >= need and 0.86 or 0.57, own >= need and 0.55 or 0.5, true)
            GameTooltip:AddLine(string.format(own >= need and "Bonus actif (%d / %d nœuds de la branche %s)." or
                "Bonus inactif : %d / %d nœuds de la branche %s.", own, need, sideName(glyph.side)),
                own >= need and 1 or 0.9, own >= need and 0.5 or 0.55, own >= need and 0 or 0.35, true)
            GameTooltip:AddLine("Clic : changer de glyphe  ·  Clic droit : retirer", 0.62, 0.57, 0.5)
        elseif isAllocated(self.nodeId) then
            GameTooltip:AddLine("Clic : sertir un glyphe", 1, 0.82, 0.3)
        end
    end
    local cost = nodeCost(node)
    if cost > 0 then
        GameTooltip:AddLine(string.format("Coût : %d point%s.", cost, cost > 1 and "s" or ""), 0.85, 0.8, 0.7)
    end
    local required = node.required or 0
    if required > 0 and not isAllocated(self.nodeId) then
        GameTooltip:AddLine(string.format("Requiert %d points dépensés sur le tableau (%d / %d).", required,
            math.min(state.spent, required), required), 1, 0.82, 0.3, true)
    end
    local missing = tierGate(self.nodeId)
    if missing > 0 and not isAllocated(self.nodeId) then
        local branch = ParagonBoard.sides and ParagonBoard.sides[node.side]
        GameTooltip:AddLine(string.format("Verrouillé : prenez tous les nœuds de %s%s d'abord (%d restants).",
            tierName(node.tier - 1), branch and (" de la branche " .. branch) or "", missing), 0.9, 0.55, 0.35, true)
    end
    if isAllocated(self.nodeId) then
        GameTooltip:AddLine("Acquis.", 1, 0.86, 0.55)
    elseif isReachable(self.nodeId) then
        if state.available >= cost then
            GameTooltip:AddLine("Clic : acquérir", 1, 0.82, 0.3)
        else
            GameTooltip:AddLine(string.format("Points insuffisants (%d disponibles).", state.available),
                0.62, 0.57, 0.5)
        end
    elseif missing == 0 then
        GameTooltip:AddLine("Pas encore accessible.", 0.62, 0.57, 0.5)
    end
    GameTooltip:Show()
    self.hovered = true
    self.glow:SetAlpha(math.min(1, self.glow:GetAlpha() + 0.35))
    if self.socket then
        for _, id in ipairs(reachOf(self.nodeId)) do
            local button = nodeButtons[id]
            if button and button.glow:IsShown() then
                button.glow:SetVertexColor(LEGENDARY[1], LEGENDARY[2], LEGENDARY[3])
                button.glow:SetAlpha(isAllocated(id) and 0.9 or 0.35)
            end
        end
    end
end

local function onNodeLeave(self)
    GameTooltip:Hide()
    self.hovered = false
    refreshNode(self.nodeId)
    if self.socket then
        for _, id in ipairs(reachOf(self.nodeId)) do
            refreshNode(id)
        end
    end
end

local function createNode(id, node)
    local size = NODE_SIZE[node.type] or NODE_SIZE[0]
    local button = CreateFrame("Button", nil, board)
    button:SetSize(size, size)
    button.baseSize = size
    button.nodeId = id

    local x, y = nodePosition(node)
    button:SetPoint("CENTER", board, "BOTTOMLEFT", x, y)

    -- A dark disc under the socket. Without it the icon sits straight on the nebula and neither reads; this
    -- is the glow texture tinted black, so it is a soft round shadow rather than a square patch.
    button.backing = button:CreateTexture(nil, "BACKGROUND")
    button.backing:SetTexture(ART .. "Paragon-Node-Glow")
    button.backing:SetVertexColor(0, 0, 0)
    button.backing:SetAlpha(0.8)
    button.backing:SetPoint("CENTER")
    button.backing:SetSize(size * 1.25, size * 1.25)

    button.glow = button:CreateTexture(nil, "ARTWORK")
    button.glow:SetTexture(ART .. "Paragon-Node-Glow")
    button.glow:SetBlendMode("ADD")
    button.glow:SetPoint("CENTER")
    button.glow:SetSize(size * 1.25, size * 1.25)

    button.icon = button:CreateTexture(nil, "ARTWORK")
    button.icon:SetTexture(node.icon)
    button.icon:SetPoint("CENTER")
    local iconScale = ICON_SCALE[node.type] or ICON_SCALE[0]
    button.icon:SetSize(size * iconScale, size * iconScale)
    button.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)

    button.ring = button:CreateTexture(nil, "OVERLAY")
    button.ring:SetTexture(ART .. (node.type == 2 and "Paragon-Node-Keystone"
        or node.type == 1 and "Paragon-Node-Notable" or "Paragon-Node-Minor"))
    button.ring:SetAllPoints()

    -- A lock over a node whose tier is still shut on its branch, shown by refreshNode
    if (node.tier or 0) > 0 and (node.side or NO_SIDE) ~= NO_SIDE then
        button.lock = button:CreateTexture(nil, "OVERLAY")
        button.lock:SetTexture("Interface\\LFGFrame\\UI-LFG-ICON-LOCK")
        button.lock:SetSize(size * 0.42, size * 0.42)
        button.lock:SetPoint("CENTER")
        button.lock:SetVertexColor(1, 0.86, 0.55)
        button.lock:Hide()
    end

    -- What it costs, on the node itself, for anything past a single point: the price is part of the decision
    local cost = nodeCost(node)
    if cost > 1 then
        local badge = button:CreateFontString(nil, "OVERLAY")
        badge:SetFont(FRIZ, math.max(11, math.floor(size * 0.28)), "OUTLINE")
        badge:SetTextColor(1, 0.86, 0.55)
        badge:SetPoint("CENTER", button, "BOTTOMRIGHT", -size * 0.14, size * 0.14)
        badge:SetText(cost)
        button.costBadge = badge
    end

    button:SetScript("OnEnter", onNodeEnter)
    button:SetScript("OnLeave", onNodeLeave)
    if node.effect == SOCKET_EFFECT then
        button.socket = true
        button.ring:SetVertexColor(1, 0.72, 0.4)
        button:RegisterForClicks("LeftButtonUp", "RightButtonUp")
        button:SetScript("OnClick", function(self, mouse)
            if not isAllocated(self.nodeId) then
                allocate(self.nodeId)
            elseif mouse == "RightButton" then
                if socketGlyph[self.nodeId] then
                    SendAddonMessage(PREFIX, "UNSOCKET\t" .. self.nodeId, "WHISPER", UnitName("player"))
                end
            else
                ShowParagonGlyphs(self.nodeId)
            end
        end)
    else
        button:SetScript("OnClick", function(self) allocate(self.nodeId) end)
    end

    button.boardX, button.boardY, button.nodeType = x, y, node.type
    button.culledIn = true
    button.detailShown = true
    button.starLevel = 0
    nodeButtons[id] = button
end

-- A heading on the board that keeps its size on screen as the board zooms out (rescaleLabels): `screen` is its scale
-- on screen, never below the board's own, and at most `maxScale` times it
local function addScaledLabel(text, x, y, fontSize, screen, maxScale, alpha)
    local holder = CreateFrame("Frame", nil, board)
    holder:SetSize(1, 1)
    local label = holder:CreateFontString(nil, "OVERLAY")
    label:SetFont(MORPHEUS, fontSize)
    label:SetShadowOffset(2, -2)
    label:SetTextColor(1, 0.86, 0.55)
    label:SetAlpha(alpha)
    label:SetPoint("CENTER", holder, "CENTER")
    label:SetText(text)
    local entry = { holder = holder, label = label, x = x, y = y, screen = screen, maxScale = maxScale }
    table.insert(scaledLabels, entry)
    placeScaledLabel(entry, 1)
    return entry
end

local function createBoard()
    buildAdjacency()

    -- The Panthéon's sky, under everything else: its stars and nebulae, clear at the centre where the three inner
    -- zones sit on the marble. One texture the board's size (buildParagonArt.py builds it from ParagonBoard.lua).
    if ParagonBoard.sky then
        local sky = board:CreateTexture(nil, "BACKGROUND")
        sky:SetTexture(ART .. "Paragon-Sky")
        sky:SetSize(BOARD_WIDTH, BOARD_HEIGHT)
        sky:SetPoint("CENTER", board, "BOTTOMLEFT", BOARD_WIDTH / 2, BOARD_HEIGHT / 2)
    end

    for id, node in pairs(ParagonBoard.nodes) do
        createNode(id, node)
    end

    -- Each zone named where it begins, in the empty wedge straight above the hub, so the name sits between
    -- two branches rather than on top of one. The Panthéon's name is a heading that stays readable from afar.
    local zones = ParagonBoard.zones or {}
    for index, zone in ipairs(zones) do
        if ParagonBoard.sky and index == #zones then
            addScaledLabel(zone.name, BOARD_WIDTH / 2, BOARD_HEIGHT / 2 + zone.radius + 60, 48, 0.85, 14, 0.8)
        elseif zone.radius > 0 then
            local label = board:CreateFontString(nil, "ARTWORK")
            label:SetFont(MORPHEUS, 40 + index * 8)
            label:SetShadowOffset(2, -2)
            label:SetTextColor(1, 0.86, 0.55)
            label:SetAlpha(0.55)
            label:SetPoint("CENTER", board, "BOTTOMLEFT", BOARD_WIDTH / 2, BOARD_HEIGHT / 2 + zone.radius)
            label:SetText(zone.name)
            local divider = board:CreateTexture(nil, "ARTWORK")
            RetailUI.SetAtlas(divider, "ChallengeMode-ThinDivider")
            divider:SetSize(320 + index * 60, 12)
            divider:SetPoint("TOP", label, "BOTTOM", 0, -6)
            divider:SetAlpha(0.7)
        end
    end

    -- Each Titan named just past the outer edge of its sigil, held inside the board: the top and bottom sigils' names
    -- would otherwise run off it (the board is only as tall as the sky). The margin covers the name at its largest.
    local labelMargin = 300
    for _, sigil in pairs(ParagonBoard.sigils or {}) do
        local distance = math.sqrt(sigil.x * sigil.x + sigil.y * sigil.y)
        local reach = distance + 780
        local x = BOARD_WIDTH / 2 + sigil.x * reach / distance
        local y = BOARD_HEIGHT / 2 + sigil.y * reach / distance
        x = math.max(labelMargin, math.min(BOARD_WIDTH - labelMargin, x))
        y = math.max(labelMargin, math.min(BOARD_HEIGHT - labelMargin, y))
        addScaledLabel(sigil.titan, x, y, 26, 0.55, 10, 0.85)
    end

    for _, link in ipairs(ParagonBoard.links) do
        local a, b = ParagonBoard.nodes[link[1]], ParagonBoard.nodes[link[2]]
        if a and b then
            local texture = board:CreateTexture(nil, "BORDER")
            local ax, ay = nodePosition(a)
            local bx, by = nodePosition(b)
            -- The Panthéon's links come from its shared set; a sigil's own lines are drawn as the sigil
            local sky = (a.tier or 0) == PANTHEON_TIER or (b.tier or 0) == PANTHEON_TIER
            if sky then
                placeSkyLink(texture, board, ax, ay, bx, by)
                texture.sky = true
            else
                placeLink(texture, board, ax, ay, bx, by)
            end
            table.insert(linkTextures, { texture = texture, a = link[1], b = link[2],
                sigil = a.sigil and a.sigil == b.sigil and a.sigil or nil,
                ax = ax, ay = ay, bx = bx, by = by, culledIn = true })
        end
    end

    board.sparkPool = {}
    for _ = 1, 8 do
        local spark = board:CreateTexture(nil, "OVERLAY")
        spark:SetBlendMode("ADD")
        spark:SetSize(SPARK_SIZE, SPARK_SIZE)
        spark:Hide()
        table.insert(board.sparkPool, spark)
    end

    board.flash = frame:CreateTexture(nil, "OVERLAY")
    board.flash:SetTexture(1, 0.72, 0.28, 1)
    board.flash:SetBlendMode("ADD")
    board.flash:SetAllPoints(canvas)
    board.flash:Hide()
end

local function createChrome()
    RetailUI.ApplyNineSlice(frame, false)

    local header = frame:CreateTexture(nil, "BORDER")
    RetailUI.SetAtlas(header, "_UI-Frame-TopTileStreaks")
    header:SetHeight(43)
    header:SetPoint("TOPLEFT", frame, "TOPLEFT", 6, -21)
    header:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -2, -21)

    local function insetCorner(atlas, point)
        local texture = frame:CreateTexture(nil, "ARTWORK")
        RetailUI.SetAtlas(texture, atlas, true)
        texture:SetPoint(point, canvas, point)
        return texture
    end
    local topLeft = insetCorner("UI-Frame-InnerTopLeft", "TOPLEFT")
    local topRight = insetCorner("UI-Frame-InnerTopRight", "TOPRIGHT")
    local bottomLeft = insetCorner("UI-Frame-InnerBotLeftCorner", "BOTTOMLEFT")
    local bottomRight = insetCorner("UI-Frame-InnerBotRight", "BOTTOMRIGHT")
    local function insetEdge(atlas, vertical, firstPoint, firstAnchor, firstRelative,
            secondPoint, secondAnchor, secondRelative)
        local texture = frame:CreateTexture(nil, "ARTWORK")
        RetailUI.SetAtlas(texture, atlas)
        if vertical then texture:SetWidth(3) else texture:SetHeight(3) end
        texture:SetPoint(firstPoint, firstAnchor, firstRelative)
        texture:SetPoint(secondPoint, secondAnchor, secondRelative)
    end
    insetEdge("!UI-Frame-InnerLeftTile", true, "TOPLEFT", topLeft, "BOTTOMLEFT",
        "BOTTOMLEFT", bottomLeft, "TOPLEFT")
    insetEdge("!UI-Frame-InnerRightTile", true, "TOPRIGHT", topRight, "BOTTOMRIGHT",
        "BOTTOMRIGHT", bottomRight, "TOPRIGHT")
    insetEdge("_UI-Frame-InnerTopTile", false, "TOPLEFT", topLeft, "TOPRIGHT",
        "TOPRIGHT", topRight, "TOPLEFT")
    insetEdge("_UI-Frame-InnerBotTile", false, "BOTTOMLEFT", bottomLeft, "BOTTOMRIGHT",
        "BOTTOMRIGHT", bottomRight, "BOTTOMLEFT")

    -- Exactly where RUI.Skin puts a window title: across the top, clear of the close button on the right
    -- and of the corner art on the left. Anything lower lands in the band and gets clipped by it.
    local title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
    title:SetPoint("TOPLEFT", frame, "TOPLEFT", 58, -4)
    title:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -26, -4)
    title:SetJustifyH("CENTER")
    title:SetText("Parangon")
    title:SetTextColor(1, 0.82, 0)

    -- Above the board, which is a scroll child and therefore draws over the window's own layers. Without
    -- this the readout and the button disappear behind the tree the moment the board fills the frame.
    hud = CreateFrame("Frame", nil, frame)
    hud:SetAllPoints(frame)
    hud:SetFrameLevel(frame:GetFrameLevel() + 15)

    -- The board fades into shadow at the top and bottom, where the header and the controls sit on it, and a
    -- little at the sides: the tree reads as lit from the middle, and the text over it stays legible
    local function shade(point, relative, size, vertical, fromTop)
        local texture = hud:CreateTexture(nil, "BACKGROUND")
        texture:SetTexture("Interface\\Buttons\\WHITE8X8")
        texture:SetPoint(point, canvas, point)
        texture:SetPoint(relative, canvas, relative)
        if vertical then
            texture:SetHeight(size)
            if fromTop then
                texture:SetGradientAlpha("VERTICAL", 0, 0, 0, 0, 0, 0, 0, 0.88)
            else
                texture:SetGradientAlpha("VERTICAL", 0, 0, 0, 0.88, 0, 0, 0, 0)
            end
        else
            texture:SetWidth(size)
            if point == "TOPLEFT" then
                texture:SetGradientAlpha("HORIZONTAL", 0, 0, 0, 0.6, 0, 0, 0, 0)
            else
                texture:SetGradientAlpha("HORIZONTAL", 0, 0, 0, 0, 0, 0, 0, 0.6)
            end
        end
    end
    shade("TOPLEFT", "TOPRIGHT", 120, true, true)
    shade("BOTTOMLEFT", "BOTTOMRIGHT", 90, true, false)
    shade("TOPLEFT", "BOTTOMLEFT", 60, false)
    shade("TOPRIGHT", "BOTTOMRIGHT", 60, false)

    local heading = hud:CreateFontString(nil, "OVERLAY")
    frame.heading = heading
    heading:SetFont(MORPHEUS, 28)
    heading:SetShadowOffset(1, -1)
    heading:SetTextColor(1, 0.86, 0.55)
    heading:SetPoint("TOPLEFT", frame, "TOPLEFT", 34, -34)
    heading:SetText("Tableau de parangon")

    local intro = hud:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    frame.intro = intro
    intro:SetPoint("TOPLEFT", heading, "BOTTOMLEFT", 2, -4)
    intro:SetWidth(430)
    intro:SetJustifyH("LEFT")
    intro:SetTextColor(0.85, 0.8, 0.7)
    intro:SetText("Chaque point renforce votre personnage pour de bon. Partez de l'Éveil, au centre, et étendez "
        .. "votre chemin nœud après nœud. L'Ascension d'une branche s'ouvre une fois son Éveil complet, sa "
        .. "Transcendance une fois son Ascension complète, son Panthéon une fois sa Transcendance complète : "
        .. "chaque sigille achevé y accorde sa Bénédiction. Les châsses reçoivent vos glyphes.")

    -- The points to spend, as the board's clock reads: an emblem, the label and the figure beside it, and the
    -- gauge of what is spent under both
    -- One column, so its pieces line up: the emblem and the figure on top, the gauge its full width under them
    local block = CreateFrame("Frame", nil, hud)
    block:SetSize(210, 140)
    block:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -32, -34)

    local emblem = CreateFrame("Frame", nil, block)
    emblem:SetSize(46, 46)
    emblem:SetPoint("TOPLEFT", block, "TOPLEFT", 2, 0)
    pointGlow = emblem:CreateTexture(nil, "BACKGROUND")
    pointGlow:SetTexture(ART .. "Paragon-Node-Glow")
    pointGlow:SetBlendMode("ADD")
    pointGlow:SetVertexColor(1, 0.78, 0.32)
    pointGlow:SetPoint("CENTER")
    pointGlow:SetSize(78, 78)
    local emblemIcon = emblem:CreateTexture(nil, "ARTWORK")
    emblemIcon:SetTexture("Interface\\Icons\\ParagonNode_Awakening")
    emblemIcon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
    emblemIcon:SetPoint("CENTER")
    emblemIcon:SetSize(46 * ICON_SCALE[1], 46 * ICON_SCALE[1])
    local emblemRing = emblem:CreateTexture(nil, "OVERLAY")
    emblemRing:SetTexture(ART .. "Paragon-Node-Notable")
    emblemRing:SetAllPoints()

    local pointLabel = block:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    pointLabel:SetPoint("TOPLEFT", emblem, "TOPRIGHT", 12, -3)
    pointLabel:SetText("Points à dépenser")

    -- The figure sits on the emblem's lower half, level with its centre line, rather than hanging under the label
    pointText = block:CreateFontString(nil, "OVERLAY")
    pointText:SetFont(MORPHEUS, POINT_FONT_SIZE)
    pointText:SetShadowOffset(1, -1)
    pointText:SetTextColor(1, 1, 1)
    pointText:SetJustifyH("LEFT")
    pointText:SetPoint("BOTTOMLEFT", emblem, "BOTTOMRIGHT", 12, 0)

    local gauge = CreateFrame("Frame", nil, block)
    gauge:SetSize(210, 12)
