-- Sized to the label rather than to a number picked in advance: a stock panel button is meant to hug its
-- text, and "Fermer" in a 170 wide plate is what made these look like placeholders.
local function createButton(label, anchorPoint, offsetX, onClick)
    local button = CreateFrame("Button", nil, hud, "UIPanelButtonTemplate")
    button:SetHeight(22)
    button:SetPoint(anchorPoint, frame, anchorPoint, offsetX, 16)
    button:SetText(label)
    button:SetWidth(math.max(96, button:GetFontString():GetStringWidth() + 32))

    button:SetScript("OnClick", onClick)
    return button
end

-- Only what is in the window is shown. The board is over a thousand nodes of four textures each plus nearly two
-- thousand links, and 3.3.5 lays out and draws every shown region of a scroll child on every scroll step, on
-- screen or not: with all of them live, panning ran at a handful of frames a second. A hidden region costs
-- nothing, so everything outside the view (plus a margin, so nothing pops in at the edge) is hidden.
--
-- The view is snapped to a coarse grid and the pass only runs when that snapped rectangle moves, so a drag
-- walks the lists a few times a second rather than every frame.
local CULL_STEP = 120
local CULL_MARGIN = 120
-- Zoomed out past this, the small nodes lose their shadow disc and glow: at that size they are specks, and
-- those two layers are half of every node's textures. Their alpha and colour still show their state.
local DETAIL_ZOOM = 0.45
-- Between these two zooms every node crossfades into a star (refreshNode): its art and the links fade out while its
-- glow grows and brightens. In steps, so a zoom through the band touches each node a handful of times, not every
-- frame. Past STAR_TO the art is hidden altogether, which is what keeps the whole sky cheap to draw.
local STAR_FROM, STAR_TO, STAR_STEPS = 0.22, 0.12, 10
local STAR_GROW = 3.2
local cullKey

local function starLevelFor(scale)
    local t = math.max(0, math.min(1, (STAR_FROM - scale) / (STAR_FROM - STAR_TO)))
    return math.floor(t * STAR_STEPS + 0.5) / STAR_STEPS
end

-- A node at a point of the crossfade, and with or without the small nodes' extras (their disc and glow)
local function applyStar(button, level, detail)
    button.starLevel = level
    button.detailShown = detail
    local fade = 1 - level
    local art = fade > 0
    local extras = art and (detail or button.nodeType ~= 0)
    for _, region in ipairs({ button.icon, button.ring, button.costBadge }) do
        region:SetAlpha(fade)
        if art then region:Show() else region:Hide() end
    end
    button.backing:SetAlpha(0.8 * fade)
    if extras then button.backing:Show() else button.backing:Hide() end
    if button.lock then button.lock:SetAlpha(fade) end
    local grow = mix(1.25, STAR_GROW, level)
    button.glow:SetSize(button.baseSize * grow, button.baseSize * grow)
    if level > 0 or extras then button.glow:Show() else button.glow:Hide() end
end

local function updateCulling(force)
    if not board or not canvas then return end
    local scale = board:GetScale()
    local width, height = canvas:GetWidth(), canvas:GetHeight()
    if not width or width <= 0 then return end

    local h, v = canvas:GetHorizontalScroll(), canvas:GetVerticalScroll()
    local left = math.floor((h - CULL_MARGIN) / CULL_STEP) * CULL_STEP
    local right = math.ceil((h + width / scale + CULL_MARGIN) / CULL_STEP) * CULL_STEP
    -- Nodes are placed from the board's bottom left; the vertical scroll counts down from its top
    local top = BOARD_HEIGHT - v
    local high = math.ceil((top + CULL_MARGIN) / CULL_STEP) * CULL_STEP
    local low = math.floor((top - height / scale - CULL_MARGIN) / CULL_STEP) * CULL_STEP
    local detail = scale >= DETAIL_ZOOM
    local level = starLevelFor(scale)

    local key = left .. ":" .. right .. ":" .. low .. ":" .. high .. (detail and "+" or "-") .. level
    if key == cullKey and not force then return end
    cullKey = key

    for id, button in pairs(nodeButtons) do
        local x, y = button.boardX, button.boardY
        local inside = x >= left and x <= right and y >= low and y <= high
        if inside ~= button.culledIn then
            button.culledIn = inside
            if inside then button:Show() else button:Hide() end
        end
        if inside and (level ~= button.starLevel or detail ~= button.detailShown) then
            applyStar(button, level, detail)
            refreshNode(id)
        end
    end

    local fade = mix(1, LINK_STAR_FADE, level)
    if fade ~= linkFade then
        linkFade = fade
        refreshLinks()
    end

    for _, link in ipairs(linkTextures) do
        local inside = math.max(link.ax, link.bx) >= left and math.min(link.ax, link.bx) <= right
            and math.max(link.ay, link.by) >= low and math.min(link.ay, link.by) <= high
        if inside ~= link.culledIn then
            link.culledIn = inside
            if inside then link.texture:Show() else link.texture:Hide() end
        end
    end
end

local function panTo(x, y)
    local scale = board:GetScale()
    local maxX = math.max(0, BOARD_WIDTH - canvas:GetWidth() / scale)
    local maxY = math.max(0, BOARD_HEIGHT - canvas:GetHeight() / scale)
    x = math.max(0, math.min(maxX, x))
    y = math.max(0, math.min(maxY, y))
    -- A drag calls this every frame, moving or not; setting the same scroll again still re-lays the board out
    if x ~= canvas:GetHorizontalScroll() then canvas:SetHorizontalScroll(x) end
    if y ~= canvas:GetVerticalScroll() then canvas:SetVerticalScroll(y) end
    updateCulling()
end

-- What sits in the middle of the viewport, in board coordinates.
local function viewCentre()
    local scale = board:GetScale()
    return canvas:GetHorizontalScroll() + canvas:GetWidth() / (2 * scale),
           canvas:GetVerticalScroll() + canvas:GetHeight() / (2 * scale)
end

local function centreOn(x, y)
    local scale = board:GetScale()
    panTo(x - canvas:GetWidth() / (2 * scale), y - canvas:GetHeight() / (2 * scale))
end

-- How far out the board may be zoomed before it stops covering the viewport. A scroll frame cannot take a
-- negative offset, so past that point there is nothing left to scroll: the board pins to the top left and
-- leaves bare ground down the right hand side instead of sitting in the middle. Zooming out stops there.
local function zoomFloor()
    local width, height = canvas:GetWidth(), canvas:GetHeight()
    if not width or width <= 0 then
        return MIN_ZOOM
    end
    return math.max(MIN_ZOOM, width / BOARD_WIDTH, height / BOARD_HEIGHT)
end

local function clampZoom(scale)
    return math.max(zoomFloor(), math.min(MAX_ZOOM, scale))
end

local function applyScale(scale)
    if math.abs(scale - board:GetScale()) > 0.0001 then
        board:SetScale(scale)
        canvas:UpdateScrollChildRect()
        rescaleLabels()
    end
end

-- Zooming has to hold the middle of the view still. SetScale alone scales the child about its own top-left
-- anchor, so the board slides into the corner as it shrinks - which is exactly what it was doing. This one is at
-- once, for opening the frame; everything the player does goes through animateView.
local function setZoom(scale)
    local cx, cy = viewCentre()
    applyScale(clampZoom(scale))
    centreOn(cx, cy)
end

-- Zoom and pan glide to where they are asked, easing out over VIEW_DURATION. The scale moves by a constant factor a
-- frame (so a zoom from the sky to a node feels even), and either the view's middle travels with it or, for the
-- wheel, the point under the cursor stays under the cursor all the way. Each frame is one SetScale and one scroll:
-- nothing is rebuilt, and the culling pass only touches what its grid says changed.
local VIEW_DURATION = 0.45
local viewAnim

local function animateView(scale, cx, cy, anchor)
    local fromX, fromY = viewCentre()
    viewAnim = { fromScale = board:GetScale(), toScale = clampZoom(scale), fromX = fromX, fromY = fromY,
        toX = cx or fromX, toY = cy or fromY, anchor = anchor, elapsed = 0 }
end

local function stepView(elapsed)
    local anim = viewAnim
    if not anim then return end
    anim.elapsed = anim.elapsed + elapsed
    local progress = math.min(1, anim.elapsed / VIEW_DURATION)
    local eased = 1 - (1 - progress) ^ 3
    local scale = anim.fromScale * (anim.toScale / anim.fromScale) ^ eased
    applyScale(scale)
    if anim.anchor then
        centreOn(anim.anchor.bx - anim.anchor.ox / scale, anim.anchor.by - anim.anchor.oy / scale)
    else
        centreOn(mix(anim.fromX, anim.toX, eased), mix(anim.fromY, anim.toY, eased))
    end
    if progress >= 1 then viewAnim = nil end
end

-- Where a zoom is headed: a second step before the first has landed builds on where the first was going
local function targetScale()
    return viewAnim and viewAnim.toScale or board:GetScale()
end

-- The board point under the cursor, and the cursor's offset from the view's middle in the canvas's own units
local function cursorAnchor()
    local x, y = GetCursorPosition()
    local effective = canvas:GetEffectiveScale()
    local ox = x / effective - (canvas:GetLeft() + canvas:GetWidth() / 2)
    local oy = (canvas:GetBottom() + canvas:GetHeight() / 2) - y / effective
    local scale = board:GetScale()
    local cx, cy = viewCentre()
    return { bx = cx + ox / scale, by = cy + oy / scale, ox = ox, oy = oy }
end

local function createFrame()
    frame = CreateFrame("Frame", "ParagonFrame", UIParent)
    frame:SetSize(WINDOW_WIDTH, WINDOW_HEIGHT)
    frame:SetPoint("CENTER")
    frame:SetFrameStrata("HIGH")
    frame:EnableMouse(true)
    frame:SetMovable(true)
    frame:Hide()

    local ground = frame:CreateTexture(nil, "BACKGROUND")
    ground:SetTexture(RetailUIFiles["ui-background-rock"], true)
    ground:SetHorizTile(true)
    ground:SetVertTile(true)
    ground:SetPoint("TOPLEFT", 2, -21)
    ground:SetPoint("BOTTOMRIGHT", -2, 2)

    -- 3.3.5 clips nothing but a scroll frame, so the pannable board has to live inside one.
    canvas = CreateFrame("ScrollFrame", "ParagonCanvas", frame)
    canvas:SetPoint("TOPLEFT", CANVAS_LEFT, -CANVAS_TOP)
    canvas:SetPoint("BOTTOMRIGHT", -CANVAS_RIGHT, CANVAS_BOTTOM)
    canvas:EnableMouse(true)
    canvas:EnableMouseWheel(true)

    local insetGround = frame:CreateTexture(nil, "BORDER")
    insetGround:SetTexture(RetailUIFiles["ui-background-marble"], true)
    insetGround:SetHorizTile(true)
    insetGround:SetVertTile(true)
    insetGround:SetAllPoints(canvas)

    board = CreateFrame("Frame", "ParagonBoardCanvas", canvas)
    board:SetSize(BOARD_WIDTH, BOARD_HEIGHT)
    canvas:SetScrollChild(board)
    -- Without this the scroll frame does not know how far the child extends and refuses to scroll
    canvas:UpdateScrollChildRect()

    canvas:SetScript("OnMouseWheel", function(_, delta)
        animateView(targetScale() * ZOOM_FACTOR ^ delta, nil, nil, cursorAnchor())
    end)

    canvas:SetScript("OnMouseDown", function(self)
        viewAnim = nil
        self.dragging = true
        self.startX, self.startY = GetCursorPosition()
        self.startH, self.startV = self:GetHorizontalScroll(), self:GetVerticalScroll()
    end)
    canvas:SetScript("OnMouseUp", function(self) self.dragging = false end)
    local pulseClock = 0
    canvas:SetScript("OnUpdate", function(self, elapsed)
        updateAnimations(elapsed)
        stepView(elapsed)

        -- With points to spend, the nodes one click away breathe, and so does the emblem: the board shows where
        -- the next point can go without a single tooltip
        pulseClock = pulseClock + elapsed
        local pulse = 0.5 + 0.5 * math.sin(pulseClock * 3)
        if state.available > 0 then
            for _, button in ipairs(reachableButtons) do
                if not button.hovered and (button.starLevel or 0) < 0.5 then
                    button.glow:SetAlpha(0.18 + 0.4 * pulse)
                end
            end
            pointGlow:SetAlpha(0.35 + 0.45 * pulse)
        else
            pointGlow:SetAlpha(0.12)
        end

        -- Release a click the server never answered, rather than wedging every click after it
        if state.pending and GetTime() - (state.pendingAt or 0) > PENDING_TIMEOUT then
            state.pending = nil
        end
        if not self.dragging then return end
        local x, y = GetCursorPosition()
        local scale = board:GetScale() * UIParent:GetEffectiveScale()
        panTo(self.startH + (self.startX - x) / scale, self.startV - (self.startY - y) / scale)
    end)

    createChrome()

    -- The window's handle: the banner across the top, and the border strip under it. Kept clear of the canvas
    -- so the two drags never fight over the same pixel.
    local mover = CreateFrame("Frame", nil, frame)
    mover:SetPoint("BOTTOMLEFT", frame, "TOPLEFT", 0, -CANVAS_TOP)
    mover:SetPoint("BOTTOMRIGHT", frame, "TOPRIGHT", 0, -CANVAS_TOP)
    mover:SetHeight(CANVAS_TOP + 52)
    mover:SetFrameLevel(frame:GetFrameLevel() + 16)
    mover:EnableMouse(true)
    mover:RegisterForDrag("LeftButton")
    mover:SetScript("OnDragStart", function() frame:StartMoving() end)
    mover:SetScript("OnDragStop", function() frame:StopMovingOrSizing() end)

    createBoard()

    -- A reset gives every point back but takes the whole tree down: it asks first
    StaticPopupDialogs["PARAGON_RESET"] = {
        text = "Réinitialiser le tableau de parangon ?\nTous vos points vous seront rendus.",
        button1 = YES,
        button2 = NO,
        OnAccept = function()
            state.pendingReset = true
            SendAddonMessage(PREFIX, "RESET", "WHISPER", UnitName("player"))
        end,
        timeout = 0,
        whileDead = 1,
        hideOnEscape = 1,
    }
    local resetButton = createButton("Réinitialiser", "BOTTOMLEFT", 24, function()
        StaticPopup_Show("PARAGON_RESET")
    end)

    -- The legend and the hint share a line of their own above the buttons, centred: the buttons take the window's
    -- whole width below them, and nothing on the one line can run into the other
    local legendRow = CreateFrame("Frame", nil, hud)
    legendRow:SetHeight(22)
    legendRow:SetPoint("BOTTOM", frame, "BOTTOM", 0, 44)
    local legend = CreateFrame("Frame", nil, legendRow)
    legend:SetHeight(22)
    legend:SetPoint("LEFT", legendRow, "LEFT", 0, 0)
    local previous
    local legendWidth = 0
    for kindId = 0, 2 do
        local kind = NODE_KINDS[kindId]
        local ring = legend:CreateTexture(nil, "OVERLAY")
        ring:SetTexture(ART .. kind.ring)
        local size = 18 + kindId * 4
        ring:SetSize(size, size)
        if previous then
            ring:SetPoint("LEFT", previous, "RIGHT", 16, 0)
            legendWidth = legendWidth + 16
        else
            ring:SetPoint("LEFT", legend, "LEFT", 0, 0)
        end
        local label = legend:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
        label:SetPoint("LEFT", ring, "RIGHT", 5, 0)
        label:SetText(kind.label)
        label:SetTextColor(kind.color[1], kind.color[2], kind.color[3])
        legendWidth = legendWidth + size + 5 + label:GetStringWidth()
        previous = label
    end
    legend:SetWidth(legendWidth)

    local hint = legendRow:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    hint:SetPoint("LEFT", legend, "RIGHT", 24, 0)
    hint:SetText("Molette : zoom  ·  Clic-glisser : déplacer")
    legendRow:SetWidth(legendWidth + 24 + hint:GetStringWidth())

    -- The controls on the right: zoom, back to the hub, and the summary of what the board gives. Each hugs its label,
    -- as the reset button does, so the row is only as wide as its words.
    local function control(label, width, onClick)
        local button = CreateFrame("Button", nil, hud, "UIPanelButtonTemplate")
        button:SetHeight(22)
        button:SetText(label)
        button:SetWidth(math.max(width, button:GetFontString():GetStringWidth() + 24))
        button:SetScript("OnClick", function()
            PlaySound("igMainMenuOptionCheckBoxOn")
            onClick()
        end)
        return button
    end
    local zoomIn = control("+", 26, function() animateView(targetScale() * ZOOM_FACTOR * ZOOM_FACTOR) end)
    zoomIn:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -24, 16)
    local zoomOut = control("-", 26, function() animateView(targetScale() / ZOOM_FACTOR / ZOOM_FACTOR) end)
    zoomOut:SetPoint("RIGHT", zoomIn, "LEFT", -4, 0)
    local recentre = control("Recentrer", 80, function()
        animateView(DEFAULT_ZOOM, BOARD_WIDTH / 2, BOARD_HEIGHT / 2)
    end)
    recentre:SetPoint("RIGHT", zoomOut, "LEFT", -8, 0)
    -- The whole sky at once: the view the Panthéon is drawn for
    local skyView = control("Vue du ciel", 80, function()
        animateView(zoomFloor(), BOARD_WIDTH / 2, BOARD_HEIGHT / 2)
    end)
    skyView:SetPoint("RIGHT", recentre, "LEFT", -8, 0)
    local bonusButton = control("Vos bonus", 80, function()
        if bonusPanel:IsShown() then bonusPanel:Hide() else bonusPanel:Show() end
    end)
    bonusButton:SetPoint("RIGHT", skyView, "LEFT", -8, 0)
    local glyphButton = control("Glyphes", 70, function()
        if glyphPanel and glyphPanel:IsShown() and not glyphPanel.socket then
            glyphPanel:Hide()
        else
            ShowParagonGlyphs(nil)
        end
    end)
    glyphButton:SetPoint("RIGHT", bonusButton, "LEFT", -8, 0)

    -- The configurations, beside the reset, as the talents keep theirs: boards saved under a name, and the
    -- recommended ones the server plans for the player's role and usable points (ParagonSystem.cpp ApplyPreset).
    -- Switching is free: the board is cleared, then taken again; glyphs go back into their sockets where it can.
    local PRESETS = {
        { id = 1, label = "Raid", title = "Tableau recommandé : raid",
          text = "Un boss, un combat long : frappes doubles, exécution, ferveur et écho passent avant ce qui " ..
                 "agit à la mort d'un ennemi ou autour de la cible." },
        { id = 2, label = "Mythique+", title = "Tableau recommandé : Mythique+",
          text = "Des packs qui tombent vite : éclaboussures, arcs, explosions et séries de victimes, " ..
                 "leur portée, et un peu plus de survie." },
    }
    local MAX_LOADOUTS = 10
    local function usablePoints()
        return math.min(state.earned or 0, state.cap or 0)
    end
    local function findLoadout(slot)
        for _, loadout in ipairs(state.loadouts) do
            if loadout.slot == slot then return loadout end
        end
    end

    StaticPopupDialogs["PARAGON_PRESET"] = {
        text = "Appliquer le %s ?\nVotre tableau sera réinitialisé gratuitement, puis vos %d points répartis " ..
               "pour votre rôle.",
        button1 = YES,
        button2 = NO,
        OnAccept = function(_, data)
            state.pendingPreset = data
            SendAddonMessage(PREFIX, "PRESET\t" .. data, "WHISPER", UnitName("player"))
        end,
        timeout = 0,
        whileDead = 1,
        hideOnEscape = 1,
    }
    StaticPopupDialogs["PARAGON_LOADOUT_APPLY"] = {
        text = "Appliquer la configuration « %s » ?\nVotre tableau sera réinitialisé gratuitement, puis repris.",
        button1 = YES,
        button2 = NO,
        OnAccept = function(_, data)
            SendAddonMessage(PREFIX, "LAPPLY\t" .. data, "WHISPER", UnitName("player"))
        end,
        timeout = 0,
        whileDead = 1,
        hideOnEscape = 1,
    }
    StaticPopupDialogs["PARAGON_LOADOUT_DELETE"] = {
        text = "Supprimer la configuration « %s » ?",
        button1 = YES,
        button2 = NO,
        OnAccept = function(_, data)
            if state.activeLoadout == data then state.activeLoadout = nil end
            SendAddonMessage(PREFIX, "LDEL\t" .. data, "WHISPER", UnitName("player"))
        end,
        timeout = 0,
        whileDead = 1,
        hideOnEscape = 1,
    }
    local function saveAs(name)
        name = name and name:gsub("[|\t\n]", ""):match("^%s*(.-)%s*$") or ""
        if name == "" then return end
        local slot
        for candidate = 1, MAX_LOADOUTS do
            if not findLoadout(candidate) then slot = candidate break end
        end
        if not slot then
            PlaySound(SOUND_DENIED)
            UIErrorsFrame:AddMessage("Vous avez déjà 10 configurations : supprimez-en une.", 1, 0.3, 0.3, 1, 3)
            return
        end
        SendAddonMessage(PREFIX, "LSAVE\t" .. slot .. "\t" .. name, "WHISPER", UnitName("player"))
    end
    StaticPopupDialogs["PARAGON_LOADOUT_NAME"] = {
        text = "Nom de la configuration (votre tableau actuel) :",
        button1 = ACCEPT,
        button2 = CANCEL,
        hasEditBox = 1,
        maxLetters = 32,
        OnShow = function(self)
            self.editBox:SetText("")
            self.editBox:SetFocus()
        end,
        OnAccept = function(self) saveAs(self.editBox:GetText()) end,
        EditBoxOnEnterPressed = function(self)
            saveAs(self:GetText())
            self:GetParent():Hide()
        end,
        EditBoxOnEscapePressed = function(self) self:GetParent():Hide() end,
        timeout = 0,
        whileDead = 1,
        hideOnEscape = 1,
    }

    -- The picker shows what the board is: a saved configuration's name, a recommended board's, or its title
    local picker = CreateFrame("Frame", "ParagonLoadoutPicker", hud, "UIDropDownMenuTemplate")
    picker:SetPoint("LEFT", resetButton, "RIGHT", -8, -2)
    UIDropDownMenu_SetWidth(picker, 128)
    local saveButton, deleteButton
    UIDropDownMenu_Initialize(picker, function()
        local info = UIDropDownMenu_CreateInfo()
        info.text = "Vos configurations"
        info.isTitle = 1
        info.notCheckable = 1
        UIDropDownMenu_AddButton(info)
        for _, loadout in ipairs(state.loadouts) do
            info = UIDropDownMenu_CreateInfo()
            info.text = loadout.name .. "  |cff888888(" .. loadout.points .. " pts)|r"
            info.checked = state.activeLoadout == loadout.slot
            info.func = function()
                local dialog = StaticPopup_Show("PARAGON_LOADOUT_APPLY", loadout.name)
                if dialog then dialog.data = loadout.slot end
            end
            UIDropDownMenu_AddButton(info)
        end
        info = UIDropDownMenu_CreateInfo()
        info.text = "|cff00ccffNouvelle configuration…|r"
        info.notCheckable = 1
        info.func = function() StaticPopup_Show("PARAGON_LOADOUT_NAME") end
        UIDropDownMenu_AddButton(info)

        info = UIDropDownMenu_CreateInfo()
        info.text = "Recommandé pour votre rôle"
        info.isTitle = 1
        info.notCheckable = 1
        UIDropDownMenu_AddButton(info)
        for _, preset in ipairs(PRESETS) do
            info = UIDropDownMenu_CreateInfo()
            info.text = preset.label
            info.checked = state.activePreset == preset.id and not state.activeLoadout
            info.tooltipTitle = preset.title
            info.tooltipText = preset.text .. "\n\n" .. string.format("Avec vos %d points. Gratuit, comme " ..
                "changer de talents.", usablePoints())
            info.func = function()
                local dialog = StaticPopup_Show("PARAGON_PRESET", preset.title:lower(), usablePoints())
                if dialog then dialog.data = preset.id end
            end
            UIDropDownMenu_AddButton(info)
        end
    end)

    saveButton = control("Enregistrer", 84, function()
        local loadout = state.activeLoadout and findLoadout(state.activeLoadout)
        if loadout then
            SendAddonMessage(PREFIX, "LSAVE\t" .. loadout.slot .. "\t" .. loadout.name, "WHISPER",
                UnitName("player"))
        else
            StaticPopup_Show("PARAGON_LOADOUT_NAME")
        end
    end)
    saveButton:SetPoint("LEFT", picker, "RIGHT", -12, 2)
    saveButton:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_TOP")
        local loadout = state.activeLoadout and findLoadout(state.activeLoadout)
        GameTooltip:SetText(loadout and ("Enregistrer « " .. loadout.name .. " »") or "Enregistrer", 1, 0.82, 0)
        GameTooltip:AddLine(loadout and "Votre tableau actuel remplace ce qu'elle contenait." or
            "Enregistre votre tableau actuel sous un nom.", 1, 1, 1, true)
        GameTooltip:Show()
    end)
    saveButton:SetScript("OnLeave", function() GameTooltip:Hide() end)
    deleteButton = control("Supprimer", 76, function()
        local loadout = state.activeLoadout and findLoadout(state.activeLoadout)
        if loadout then
            local dialog = StaticPopup_Show("PARAGON_LOADOUT_DELETE", loadout.name)
            if dialog then dialog.data = loadout.slot end
        end
    end)
    deleteButton:SetPoint("LEFT", saveButton, "RIGHT", 4, 0)

    -- The picker's text and the delete button follow the board (refreshLoadouts, from the server's messages). A
    -- recommended board shows its label in the menu's blue: "Recommandé : Mythique+" does not fit the picker.
    refreshLoadouts = function()
        local loadout = state.activeLoadout and findLoadout(state.activeLoadout)
        local preset = state.activePreset and PRESETS[state.activePreset]
        UIDropDownMenu_SetText(picker, loadout and loadout.name or
            (preset and ("|cff00ccff" .. preset.label .. "|r")) or "Configurations")
        if loadout then deleteButton:Enable() else deleteButton:Disable() end
    end
    refreshLoadouts()

    -- The summary: every stat the board gives, added up, and the major nodes by name
    bonusPanel = CreateFrame("Frame", nil, hud)
    bonusPanel:SetWidth(230)
    bonusPanel:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -24, -184)
    bonusPanel:SetBackdrop({
        bgFile = "Interface\\Tooltips\\UI-Tooltip-Background",
        edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
        tile = true, tileSize = 16, edgeSize = 14,
        insets = { left = 4, right = 4, top = 4, bottom = 4 },
    })
    bonusPanel:SetBackdropColor(0.04, 0.03, 0.02, 0.9)
    bonusPanel:SetBackdropBorderColor(0.75, 0.6, 0.35, 1)
    bonusPanel:EnableMouse(true)
    bonusPanel:Hide()
    local bonusTitle = bonusPanel:CreateFontString(nil, "OVERLAY")
    bonusTitle:SetFont(MORPHEUS, 17)
    bonusTitle:SetTextColor(1, 0.86, 0.55)
    bonusTitle:SetPoint("TOPLEFT", 12, -10)
    bonusTitle:SetText("Vos bonus")
    -- The list scrolls (wheel, or the stock scroll bar) once it is taller than the room above the buttons
    local bonusScroll = CreateFrame("ScrollFrame", "ParagonBonusScroll", bonusPanel, "UIPanelScrollFrameTemplate")
    bonusScroll:SetPoint("TOPLEFT", bonusTitle, "BOTTOMLEFT", 0, -6)
    bonusScroll:SetPoint("BOTTOMRIGHT", bonusPanel, "BOTTOMRIGHT", -30, 10)
    local bonusContent = CreateFrame("Frame", nil, bonusScroll)
    bonusContent:SetSize(BONUS_TEXT_WIDTH, 10)
    bonusScroll:SetScrollChild(bonusContent)
    bonusPanel.scroll, bonusPanel.content = bonusScroll, bonusContent
    bonusText = bonusContent:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    bonusText:SetPoint("TOPLEFT", bonusContent, "TOPLEFT", 0, 0)
    bonusText:SetWidth(BONUS_TEXT_WIDTH)
    bonusText:SetJustifyH("LEFT")
    bonusText:SetSpacing(2)

    -- Escape closes it. This is how 3.3.5 does it: SetPropagateKeyboardInput arrived two expansions later, and
    -- a hand-rolled OnKeyDown would swallow every other key the frame happens to have focus for.
    tinsert(UISpecialFrames, "ParagonFrame")

    -- Hung off OnHide so the button, Escape and anything else that closes the frame all behave the same.
    frame:SetScript("OnHide", function()
        PlaySound(SOUND_CLOSE)
        state.open = false
    end)
end

--------------------------------------------------------------------------------
-- Glyphs: the collection panel and the items' tooltips
--------------------------------------------------------------------------------

local GLYPH_BUTTON, GLYPH_GAP = 40, 10
local GLYPH_COLUMNS = 6

local function glyphCopies(glyphId)
    local glyph = ParagonBoard.glyphs[glyphId]
    return glyph and GetItemCount(glyph.item) or 0
end

-- A glyph's lines, for an item tooltip and for the panel's: what it does, its condition, its level
local function addGlyphLines(tooltip, glyphId, withName)
    local glyph = ParagonBoard.glyphs[glyphId]
    if not glyph then return end
    local known = glyphState[glyphId]
    if withName then
        tooltip:AddLine(glyph.name, LEGENDARY[1], LEGENDARY[2], LEGENDARY[3])
    end
    tooltip:AddLine(string.format("Glyphe de parangon · branche %s", sideName(glyph.side)), 1, 0.82, 0.35)
    if known then
        local progress = known.needed > 0 and string.format(" (%d / %d)", known.experience, known.needed) or ""
        tooltip:AddLine(string.format("Niveau %d / %d%s", known.level, GLYPH_MAX_LEVEL, progress), 1, 1, 1)
    end
    -- What it does, in two parts: what any socketed glyph does, then its own bonus and what turns it on
    local level = known and known.level or 1
    tooltip:AddLine(" ")
    tooltip:AddLine(string.format("Serti dans une châsse, il renforce de %d%% les nœuds que vous avez pris autour "
        .. "d'elle (jusqu'à %d liens).", glyphShare(level), GLYPH_RADIUS), 0.9, 0.85, 0.7, true)
    tooltip:AddLine("Bonus : " .. glyph.description, 1, 0.86, 0.55, true)
    tooltip:AddLine(string.format("Le bonus s'active avec %d nœuds de la branche %s pris autour de la châsse.",
        glyph.need, sideName(glyph.side)), 0.75, 0.7, 0.6, true)
    tooltip:AddLine(" ")
    if known and known.socket > 0 then
        local own, need = glyphCondition(glyphId, known.socket)
        tooltip:AddLine(string.format(own >= need and "Serti : bonus actif (%d / %d nœuds de la branche %s)." or
            "Serti : bonus inactif, %d / %d nœuds de la branche %s.", own, need, sideName(glyph.side)), 1, 0.5, 0, true)
    elseif known then
        tooltip:AddLine("Dans votre collection : sertissez-le depuis le tableau de parangon.", 0.75, 0.7, 0.6, true)
    else
        tooltip:AddLine("Utilisez-le pour l'ajouter à votre collection.", 0.75, 0.7, 0.6, true)
    end
    if known and known.level < GLYPH_MAX_LEVEL then
        tooltip:AddLine("Pour le monter de niveau : absorbez ses doubles, ou gardez-le serti en clé +10, au Donjon "
            .. "infini (étage 50 et plus) ou en raid héroïque.", 0.62, 0.57, 0.5, true)
    end
end

-- The glyph items' tooltips get their level and effect: the item itself only carries its lore
local function onTooltipSetItem(tooltip)
    local _, link = tooltip:GetItem()
    local item = link and tonumber(link:match("item:(%d+)"))
    local glyphId = item and glyphByItem[item]
    if glyphId then
        addGlyphLines(tooltip, glyphId, false)
        tooltip:Show()
    end
end
GameTooltip:HookScript("OnTooltipSetItem", onTooltipSetItem)
ItemRefTooltip:HookScript("OnTooltipSetItem", onTooltipSetItem)

local function socketLabel(socket)
    local node = ParagonBoard.nodes[socket]
    if not node then return "" end
    return string.format("%s (%s)", node.name, sideName(node.side))
end

local function refreshGlyphPanel()
    if not glyphPanel then return end
    local known = 0
    for id, button in pairs(glyphButtons) do
        local state = glyphState[id]
        local copies = glyphCopies(id)
        if state then known = known + 1 end
        button.icon:SetDesaturated(not state)
        button:SetAlpha(state and 1 or (copies > 0 and 0.85 or 0.35))
        if state then button.border:Show() else button.border:Hide() end
        button.level:SetText(state and state.level or "")
        button.copies:SetText(copies > 0 and ("x" .. copies) or "")
        if state and state.socket > 0 then button.set:Show() else button.set:Hide() end
    end
    if glyphPanel.socket then
        glyphPanel.subtitle:SetText("Choisissez le glyphe à sertir dans la " .. socketLabel(glyphPanel.socket) .. ".")
    else
        glyphPanel.subtitle:SetFormattedText("Votre collection : %d / %d glyphes.", known, #ParagonBoard.glyphs)
    end
end

local function createGlyphPanel()
    glyphPanel = CreateFrame("Frame", nil, hud)
    local width = GLYPH_COLUMNS * GLYPH_BUTTON + (GLYPH_COLUMNS - 1) * GLYPH_GAP + 28
    glyphPanel:SetSize(width, 5 * (GLYPH_BUTTON + GLYPH_GAP) + 128)
    glyphPanel:SetPoint("TOPLEFT", frame.intro, "BOTTOMLEFT", -4, -12)
    glyphPanel:SetBackdrop({
        bgFile = "Interface\\Tooltips\\UI-Tooltip-Background",
        edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
        tile = true, tileSize = 16, edgeSize = 14,
        insets = { left = 4, right = 4, top = 4, bottom = 4 },
    })
    glyphPanel:SetBackdropColor(0.04, 0.03, 0.02, 0.92)
    glyphPanel:SetBackdropBorderColor(0.75, 0.6, 0.35, 1)
    glyphPanel:EnableMouse(true)
    glyphPanel:Hide()

    local title = glyphPanel:CreateFontString(nil, "OVERLAY")
    title:SetFont(MORPHEUS, 17)
    title:SetTextColor(1, 0.86, 0.55)
    title:SetPoint("TOPLEFT", 12, -10)
    title:SetText("Glyphes de parangon")
    glyphPanel.subtitle = glyphPanel:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    glyphPanel.subtitle:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4)
    glyphPanel.subtitle:SetWidth(width - 24)
    glyphPanel.subtitle:SetJustifyH("LEFT")
    glyphPanel.subtitle:SetTextColor(0.85, 0.8, 0.7)

    -- One column a branch, five glyphs down each
    local columns = {}
    for id, glyph in pairs(ParagonBoard.glyphs) do
        columns[glyph.side] = columns[glyph.side] or {}
        table.insert(columns[glyph.side], id)
    end
    for side = 0, GLYPH_COLUMNS - 1 do
        local x = 14 + side * (GLYPH_BUTTON + GLYPH_GAP)
        local header = glyphPanel:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
        header:SetPoint("TOP", glyphPanel, "TOPLEFT", x + GLYPH_BUTTON / 2, -60)
        header:SetText(sideName(side))
        local ids = columns[side] or {}
        table.sort(ids)
        for row, id in ipairs(ids) do
            local glyph = ParagonBoard.glyphs[id]
            local button = CreateFrame("Button", nil, glyphPanel)
            button:SetSize(GLYPH_BUTTON, GLYPH_BUTTON)
            button:SetPoint("TOPLEFT", glyphPanel, "TOPLEFT", x, -76 - (row - 1) * (GLYPH_BUTTON + GLYPH_GAP))
            button.icon = button:CreateTexture(nil, "ARTWORK")
            button.icon:SetAllPoints()
            button.icon:SetTexture(glyph.icon)
            button.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
            -- The legendary border of a glyph known
            button.border = button:CreateTexture(nil, "OVERLAY")
            button.border:SetTexture("Interface\\Buttons\\UI-ActionButton-Border")
            button.border:SetBlendMode("ADD")
            button.border:SetVertexColor(LEGENDARY[1], LEGENDARY[2], LEGENDARY[3])
            button.border:SetPoint("CENTER")
            button.border:SetSize(GLYPH_BUTTON * 1.8, GLYPH_BUTTON * 1.8)
            button.level = button:CreateFontString(nil, "OVERLAY", "NumberFontNormal")
            button.level:SetPoint("BOTTOMRIGHT", -2, 2)
            button.copies = button:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
            button.copies:SetPoint("TOPLEFT", 2, -2)
            button.set = button:CreateTexture(nil, "OVERLAY")
            button.set:SetTexture("Interface\\Buttons\\UI-CheckBox-Check")
            button.set:SetSize(18, 18)
            button.set:SetPoint("TOPRIGHT", 4, 4)
            button:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square", "ADD")
            button:RegisterForClicks("LeftButtonUp", "RightButtonUp")
            button.glyphId = id
            button:SetScript("OnClick", function(self, mouse)
                local known = glyphState[self.glyphId]
                local copies = glyphCopies(self.glyphId)
                if mouse == "RightButton" or not known then
                    -- A copy from the bags: learnt when new, absorbed as experience when known
                    if copies > 0 then
                        SendAddonMessage(PREFIX, "ABSORB\t" .. self.glyphId, "WHISPER", UnitName("player"))
                    else
                        PlaySound(SOUND_DENIED)
                    end
                elseif glyphPanel.socket then
                    SendAddonMessage(PREFIX, "SOCKET\t" .. glyphPanel.socket .. "\t" .. self.glyphId, "WHISPER",
                        UnitName("player"))
                else
                    UIErrorsFrame:AddMessage("Cliquez d'abord une châsse acquise sur le tableau.", 1, 0.82, 0.3, 1, 3)
                end
            end)
            button:SetScript("OnEnter", function(self)
                PlaySound(SOUND_HOVER)
                GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
                addGlyphLines(GameTooltip, self.glyphId, true)
                GameTooltip:AddLine(" ")
                GameTooltip:AddLine(ParagonBoard.glyphs[self.glyphId].lore, 1, 0.82, 0, true)
                local copies = glyphCopies(self.glyphId)
                if copies > 0 then
                    GameTooltip:AddLine(string.format("Clic droit : %s (%d dans vos sacs)",
                        glyphState[self.glyphId] and "absorber un double" or "apprendre", copies), 1, 0.82, 0.3)
                end
                if glyphState[self.glyphId] and glyphPanel.socket then
                    GameTooltip:AddLine("Clic : sertir ici", 1, 0.82, 0.3)
                end
                GameTooltip:Show()
            end)
            button:SetScript("OnLeave", function() GameTooltip:Hide() end)
            glyphButtons[id] = button
        end
    end

    local hint = glyphPanel:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
    hint:SetPoint("BOTTOMLEFT", 12, 12)
    hint:SetWidth(width - 24)
    hint:SetJustifyH("LEFT")
    hint:SetText("Clic sur une châsse acquise, puis sur un glyphe : sertir. Clic droit sur la châsse : retirer. "
        .. "Clic droit sur un glyphe : apprendre ou absorber un exemplaire de vos sacs.")

    glyphPanel.refresh = refreshGlyphPanel
    glyphPanel:SetScript("OnHide", function(self) self.socket = nil end)
    glyphPanel:RegisterEvent("BAG_UPDATE")
    glyphPanel:SetScript("OnEvent", function(self) if self:IsShown() then refreshGlyphPanel() end end)
end

-- Opens the glyph panel, for a socket or on its own
function ShowParagonGlyphs(socket)
    if not frame then return end
    if not glyphPanel then createGlyphPanel() end
    glyphPanel.socket = socket
    glyphPanel:Show()
    refreshGlyphPanel()
    PlaySound("igCharacterInfoOpen")
end

-- The socket each glyph sits in, the other way round, for the board
local function indexSockets()
    socketGlyph = {}
    for id, glyph in pairs(glyphState) do
        if glyph.socket > 0 then socketGlyph[glyph.socket] = id end
    end
end

local function readGlyph(text)
    local id, level, experience, needed, socket = text:match("^(%d+):(%d+):(%d+):(%d+):(%d+)$")
    if not id then return end
    glyphState[tonumber(id)] = { level = tonumber(level), experience = tonumber(experience),
        needed = tonumber(needed), socket = tonumber(socket) }
end

local function glyphsChanged()
    indexSockets()
    if frame and frame:IsShown() then
        refreshAll()
    end
    refreshGlyphPanel()
end

--------------------------------------------------------------------------------
-- Server messages
--------------------------------------------------------------------------------

local function onAllocated(id)
    local node = ParagonBoard.nodes[id]
    if not node then return end

    state.allocated[id] = true
    state.pending = nil

    local button = nodeButtons[id]
    local neighbours = {}
    for _, neighbour in ipairs(adjacency[id] or {}) do
        if not isAllocated(neighbour) then
            table.insert(neighbours, neighbour)
        end
    end

    -- Light the link that was just completed, from whichever held node it came from
    for _, link in ipairs(linkTextures) do
        if (link.a == id and isAllocated(link.b)) or (link.b == id and isAllocated(link.a)) then
            local sx, sy, ex, ey = link.ax, link.ay, link.bx, link.by
            if link.a == id then sx, sy, ex, ey = link.bx, link.by, link.ax, link.ay end
            animateLink(link.texture, sx, sy, ex, ey)
            break
        end
    end

    animateNode(button)
    refreshAll()

    -- Staggered so the newly available ring spreads outward rather than appearing all at once
    for index, neighbour in ipairs(neighbours) do
        local neighbourButton = nodeButtons[neighbour]
        if neighbourButton then
            neighbourButton:SetAlpha(ALPHA_LOCKED)
            animateRipple(neighbourButton, 0.05 * index)
        end
    end

    if node.type == 2 then
        PlaySound(SOUND_NOTABLE)
        PlaySound(SOUND_KEYSTONE)
        flashCanvas()
    elseif node.type == 1 then
        PlaySound(SOUND_NOTABLE)
    else
        PlaySound(SOUND_MINOR)
    end
end

local function handle(message)
    local command, rest = message:match("^([^\t]+)\t?(.*)$")
    if not command then return end

    if command == "OPEN" or command == "STATE" then
        local signature, cap, available, earned, spent = rest:match("^(%d+)\t(%d+)\t(%d+)\t(%d+)\t(%d+)$")
        if not signature then return end

        if tonumber(signature) ~= ParagonBoard.signature then
            UIErrorsFrame:AddMessage(
                "Tableau de parangon désynchronisé : le patch du client ne correspond pas au serveur.",
                1, 0.3, 0.3, 1, 6)
        end

        state.cap, state.available = tonumber(cap), tonumber(available)
        state.earned, state.spent = tonumber(earned), tonumber(spent)
        if state.pendingReset then
            state.activeLoadout, state.activePreset = nil, nil
            -- Glyph_MajorDestroy is audibly Glyph_MajorCreate reversed, so a board being cleared sounds like
            -- the undoing of the nodes that built it
            PlaySound(SOUND_RESET)
            state.pendingReset = nil
        end
        state.allocated = {}
        state.receiving = true
        state.opening = (command == "OPEN")
        return
    end

    if command == "NODES" then
        if not state.receiving then return end
        for id in rest:gmatch("(%d+)") do
            state.allocated[tonumber(id)] = true
        end
        return
    end

    if command == "DONE" then
        state.receiving = false
        if not frame then createFrame() end
        refreshAll()
        if state.opening and not state.open then
            state.open = true
            frame:Show()
            PlaySound(SOUND_OPEN)
            -- Start centred on the hub; the board reads from the middle outward
            setZoom(DEFAULT_ZOOM)
            centreOn(BOARD_WIDTH / 2, BOARD_HEIGHT / 2)
            -- It fades in as the challenge board does, rather than appearing at once
            frame:SetAlpha(0)
            addAnimation({
                duration = 0.25,
                step = function(_, progress) frame:SetAlpha(1 - (1 - progress) ^ 2) end,
                finish = function() frame:SetAlpha(1) end,
            })
        end
        state.opening = false
        return
    end

    if command == "GAINED" then
        local id, available, spent = rest:match("^(%d+)\t(%d+)\t(%d+)$")
        if not id then return end
        state.available, state.spent = tonumber(available), tonumber(spent)
        onAllocated(tonumber(id))
        -- A node taken by hand: the board is no longer the recommended one. A configuration stays picked, so
        -- Enregistrer writes the new nodes into it.
        if state.activePreset then
            state.activePreset = nil
            if refreshLoadouts then refreshLoadouts() end
        end
        return
    end

    -- The saved configurations come with every state (SendLoadouts): LC clears the list, an L line per one
    if command == "LC" then
        state.loadouts = {}
        if refreshLoadouts then refreshLoadouts() end
        return
    end

    if command == "L" then
        local slot, points, name = rest:match("^(%d+)\t(%d+)\t(.*)$")
        if slot then
            table.insert(state.loadouts, { slot = tonumber(slot), points = tonumber(points), name = name })
            if refreshLoadouts then refreshLoadouts() end
        end
        return
    end

    if command == "LSAVED" then
        state.activeLoadout, state.activePreset = tonumber(rest), nil
        PlaySound(SOUND_NOTABLE)
        if refreshLoadouts then refreshLoadouts() end
        return
    end

    if command == "LA" then
        -- A configuration taken again: the board just redrawn (STATE) flares as a recommended one does
        local slot = rest:match("^(%d+)")
        state.activeLoadout, state.activePreset = tonumber(slot), nil
        PlaySound(SOUND_NOTABLE)
        PlaySound(SOUND_KEYSTONE)
        if frame and frame:IsShown() then flashCanvas() end
        if refreshLoadouts then refreshLoadouts() end
        return
    end

    if command == "POINT" then
        local available, earned = rest:match("^(%d+)\t(%d+)$")
        if available then
            state.available, state.earned = tonumber(available), tonumber(earned)
            if frame and frame:IsShown() then refreshHeader() end
        end
        return
    end

    if command == "PXP" then
        local level, experience, needed = rest:match("^(%d+)\t(%d+)\t(%d+)$")
        if level then
            state.level, state.experience = tonumber(level), tonumber(experience)
            state.needed = math.max(1, tonumber(needed))
            if frame and frame:IsShown() then refreshHeader() end
        end
        return
    end

    if command == "PLEVEL" then
        local level = tonumber(rest)
        if level then ShowParagonLevelToast(level) end
        return
    end

    if command == "GLYPHBEGIN" then
        glyphState = {}
        return
    end

    if command == "GLYPHS" then
        for entry in rest:gmatch("[^,]+") do
            readGlyph(entry)
        end
        return
    end

    if command == "GLYPHEND" then
        glyphsChanged()
        return
    end

    if command == "GLYPH" then
        readGlyph(rest)
        glyphsChanged()
        return
    end

    if command == "GLYPHNEW" then
        PlaySound(SOUND_NOTABLE)
        return
    end

    if command == "SOCKETED" then
        local socket, glyphId = rest:match("^(%d+)\t(%d+)$")
        PlaySound(tonumber(glyphId or 0) > 0 and SOUND_NOTABLE or SOUND_RESET)
        if glyphPanel and glyphPanel.socket then glyphPanel:Hide() end
        local button = socket and nodeButtons[tonumber(socket)]
        if button then animateNode(button) end
        return
    end

    if command == "BLESSING" then
        -- A sigil's last star: the figure lights up (refreshLinks), and the board flares as for a keystone
        PlaySound(SOUND_KEYSTONE)
        if frame and frame:IsShown() then flashCanvas() end
        return
    end

    if command == "PRESETDONE" then
        -- A recommended board applied: the board just redrawn (STATE) flares as for a keystone
        state.pendingPreset = nil
        state.activePreset, state.activeLoadout = tonumber(rest), nil
        if refreshLoadouts then refreshLoadouts() end
        PlaySound(SOUND_NOTABLE)
        PlaySound(SOUND_KEYSTONE)
        if frame and frame:IsShown() then flashCanvas() end
        return
    end

    if command == "ERROR" then
        state.pending = nil
        state.pendingReset = nil
        state.pendingPreset = nil
        PlaySound(SOUND_DENIED)
        UIErrorsFrame:AddMessage(rest, 1, 0.3, 0.3, 1, 3)
        return
    end
end

--------------------------------------------------------------------------------
-- Level-up alert
--------------------------------------------------------------------------------

-- A paragon level is announced the way the game announces an achievement: the stock achievement alert (FrameXML
-- AlertFrames.xml), with its own art, glow, shine and fade, above the action bars. The header says what it is, the
-- shield carries the point it pays, and a click opens the board.
local ALERT_ICON = "Interface\\Icons\\ParagonNode_Awakening"
local ALERT_FRENCH = GetLocale() == "frFR"
local alert

local function OpenBoardFromAlert()
    SendAddonMessage(PREFIX, "OPEN", "WHISPER", UnitName("player"))
end

function ShowParagonLevelToast(level)
    if not alert then
        alert = CreateFrame("Button", "ParagonLevelAlertFrame", UIParent, "AchievementAlertFrameTemplate")
        alert:SetScript("OnClick", OpenBoardFromAlert)
        alert:SetScript("OnHide", nil)
        _G[alert:GetName() .. "IconTexture"]:SetTexture(ALERT_ICON)
        _G[alert:GetName() .. "Unlocked"]:SetText(ALERT_FRENCH and "Niveau de parangon" or "Paragon level")
        local shield = _G[alert:GetName() .. "Shield"]
        shield.icon:SetTexture([[Interface\AchievementFrame\UI-Achievement-Shields]])
        alert.points = _G[alert:GetName() .. "ShieldPoints"]
    end

    -- Where an achievement alert would stand, above one already on show
    alert:ClearAllPoints()
    if AchievementAlertFrame1 and AchievementAlertFrame1:IsShown() then
        alert:SetPoint("BOTTOM", AchievementAlertFrame1, "TOP", 0, -10)
    else
        alert:SetPoint("BOTTOM", UIParent, "BOTTOM", 0, 128)
    end

    _G[alert:GetName() .. "Name"]:SetText(format(ALERT_FRENCH and "Niveau %d atteint" or "Level %d reached", level))
    alert.points:SetText("+1")
    AlertFrame_AnimateIn(alert)
    PlaySound("LEVELUPSOUND")
end

local listener = CreateFrame("Frame")
listener:RegisterEvent("CHAT_MSG_ADDON")
listener:RegisterEvent("PLAYER_ENTERING_WORLD")
listener:SetScript("OnEvent", function(self, event, prefix, message, _, sender)
    if event == "PLAYER_ENTERING_WORLD" then
        -- The glyphs' levels, for their tooltips, without opening the board first
        if not self.glyphsAsked then
            self.glyphsAsked = true
            SendAddonMessage(PREFIX, "GLYPHSYNC", "WHISPER", UnitName("player"))
        end
        return
    end
    if event ~= "CHAT_MSG_ADDON" or prefix ~= PREFIX or sender ~= UnitName("player") then
        return
    end
    handle(message)
end)

-- Also reachable without walking to the keeper, which matters while building the board out.
SLASH_PARAGON1 = "/paragon"
SlashCmdList["PARAGON"] = function()
    SendAddonMessage(PREFIX, "OPEN", "WHISPER", UnitName("player"))
end
